/*eslint-disable*/import type{Messages}from"@lingui/core";export const messages=JSON.parse("{\"-C4dIk\":[\"Les grilles qui exigent une chaîne forcée sont rares et coûteuses à chercher à la demande\u202F; Suuudokuuu intègre donc un corpus qui a déjà été contrôlé par un solveur à couverture exacte de type Dancing Links et par un solveur à masques de bits, coté, puis filtré pour ne garder que les grilles à chaîne forcée avant d’être empaqueté.\"],\"-Elizp\":[\"Quand les intersections deviennent automatiques, passez au <0>recueil de sudoku Difficile à imprimer</0> pour les fish et les wings. Revenez au <1>sudoku Facile à imprimer</1> pour un échauffement aux singletons seuls, ou jouez à Moyen sur écran sur la <2>page Sudoku Moyen</2>.\"],\"-bYKwe\":[\"Comprend Everest (SE 11.9), Platinum Blonde (SE 10.9) et AI Escargot (SE 10.6).\"],\"-iJ7nh\":[[\"clueCount\"],\" chiffres donnés sur 81 cases, qui se résolvent avec de simples dernières cases libres et des singletons nus.\"],\"-vAdwL\":[\"Techniques\"],\"0Ktk6B\":[\"Mis à jour le <0>\",[\"formattedDate\"],\"</0>\"],\"0L9JZJ\":[\"Combien de grilles contient le PDF de sudoku Facile à imprimer\u202F?\"],\"0MRfHz\":[\"Sudoku Infini\"],\"0RoXsf\":[\"Le PDF de sudoku Cauchemar à imprimer est-il gratuit\u202F?\"],\"0Sy9Gs\":[\"Combien de grilles contient le PDF de sudoku Enfer à imprimer\u202F?\"],\"0bpi83\":[\"Recueils de sudoku à imprimer par difficulté\"],\"0r_rbI\":[[\"SITE_NAME\"],\" contient-il des publicités\u202F?\"],\"0zmlwH\":[\"Télécharger \",[\"title\"],\" (PDF)\"],\"18cwop\":[\"<0>Facile</0>\xA0: \",[\"easyClueCount\"],\" chiffres donnés, avec la garantie d’avoir besoin d’au moins un singleton caché, et de rien de plus.\"],\"1KnfS2\":[\"Combien de chiffres donnés compte un sudoku Cauchemar\u202F?\"],\"1Lvcgc\":[\"Grille 1 du recueil Cauchemar, parmi les \",[\"PRINTABLE_BOOKLET_SIZE\"],\" du PDF.\"],\"1SEI1B\":[\"C’est le niveau généré le plus difficile de Suuudokuuu, mesuré à SE \",[\"seRatingRange\"],\" sur un échantillon de \",[\"sampleSize\"],\" grilles. Chacune exige une logique de chaîne ou de coloriage en plus des fish et des wings que Difficile exige déjà.\"],\"1ZWQlV\":[\"Comment imprimer ces grilles\"],\"1ZluOW\":[\"Pourquoi le papier aide avec les chaînes\"],\"1aVkEA\":[\"Une technique d’intersection travaille sur le recoupement d’un bloc et d’une ligne ou d’une colonne. Une paire ou un triplet pointé repère un chiffre limité à deux ou trois cases d’un bloc qui sont toutes sur une même ligne, et l’efface du reste de cette ligne\u202F; la réduction bloc-ligne en est l’image miroir, qui part d’une ligne pour revenir vers un bloc. Les paires nues et cachées sont la porte d’entrée du raisonnement par sous-ensembles\xA0: deux cases qui partagent exactement deux candidats, ou deux chiffres qui n’entrent que dans deux cases d’une unité, verrouillent ces deux cases et les isolent du reste de l’unité. Aucune de ces techniques ne place directement un chiffre, elles ne font qu’éliminer des candidats, mais avec \",[\"clueCount\"],\" chiffres donnés, une grille Moyen en cache toujours au moins une, et cela suffit généralement à débloquer un nouveau singleton nu un ou deux coups plus tard. Le niveau est aussi plafonné de l’autre côté\xA0: il ne demande jamais de fish, de wing ni de chaîne, car une grille qui en exige est promue en Difficile.\"],\"27Qok0\":[\"Aucune grille du niveau n’exige de fish, de wing ni de chaîne\xA0: une grille qui en exige est promue en Difficile.\"],\"2Dg4GX\":[\"Soyons honnêtes\xA0: quelle difficulté\u202F?\"],\"2Lb_CG\":[\"Cherchez les singletons cachés\"],\"2N-XHb\":[\"Sudoku pour seniors\"],\"2gnUkr\":[\"Novice\"],\"2wuXBd\":[\"La toute première chose à vérifier est si un bloc, une ligne ou une colonne n’a plus qu’un seul chiffre manquant. Si huit des neuf cases d’une unité sont déjà remplies, la neuvième doit prendre le chiffre qui manque encore à l’unité\xA0: pas de candidats à comparer, juste une soustraction.\"],\"3-aLmy\":[\"Oui. Les deux figurent dans l’ensemble Infini, avec Platinum Blonde et Golden Nugget. Chaque partie mélange les chiffres, les lignes et les colonnes, si bien que la grille a un aspect différent à chaque fois alors que la grille reste la même.\"],\"35wRk8\":[\"C’est le niveau le plus facile que propose Suuudokuuu, et le générateur le garantit\xA0: une grille n’est livrée comme Novice qu’une fois terminée par un solveur limité aux dernières cases libres et aux singletons nus. Notre échantillon se mesure à SE \",[\"seRatingRange\"],\", sans suivi de candidats et sans risque d’être forcé de deviner.\"],\"367Cn7\":[\"Quelle technique exige un recueil de sudoku Facile\u202F?\"],\"3DJmkH\":[\"Notre moteur de techniques reconnaît que ces grilles dépassent sa portée. Il connaît tous les motifs de l’<0>index des techniques</0>, jusqu’au <1/> et au <2/>, et il ne peut toujours pas terminer seul une seule grille Infini. Cela ne veut pas dire qu’elles obligent à deviner\u202F; cela veut dire qu’elles exigent des réseaux forcés plus longs que ceux que le moteur implémente. Les indices sont désactivés par défaut en Cauchemar, Enfer et Infini, et un réglage permet de les réactiver si vous voulez l’aide du moteur aussi loin qu’elle va.\"],\"3SwmIF\":[\"Quand vous lancez une partie d’Infini, l’application choisit l’une de ces grilles et la déguise. Elle renomme les chiffres, mélange les lignes au sein de leur bande, les colonnes au sein de leur pile ainsi que les bandes et les piles elles-mêmes, et reflète parfois la grille selon sa diagonale. Rien de tout cela ne change la logique ni la cote\xA0: l’Everest auquel vous jouez reste l’Everest, il n’a simplement pas l’aspect de l’image ci-dessous.\"],\"3a3AKD\":[\"Ce recueil de sudoku Novice à imprimer est-il gratuit\u202F?\"],\"3c-rtT\":[\"Télécharger dans l’App Store\"],\"3l9jCt\":[\"Combien de niveaux de difficulté Suuudokuuu propose-t-il\u202F?\"],\"3m4lq2\":[\"Un fish est facile à manquer sur un écran où l’on ne voit que quelques cases à la fois, car le motif se trouve dans les emplacements possibles d’un chiffre sur deux, trois ou quatre lignes entières en même temps. Sur une grille imprimée complète, vous pouvez marquer les positions restantes de ce chiffre le long d’une colonne et lire la forme sur la page. Les wings demandent la vue inverse\xA0: quelques cases bivaluées qui se voient à travers la grille, et les entourer au crayon rend le recoupement évident. Comme ces deux familles sont faciles à mal appliquer les premières fois, vérifier votre travail avec les pages de solutions à la fin vaut la peine à chaque fois, jusqu’à ce que la forme devienne automatique.\"],\"4-X0DJ\":[\"Disponible sur Google Play\"],\"4DuWbm\":[\"<0>Règle de la ligne.</0> Chacune des neuf lignes doit contenir une seule fois chaque chiffre de 1 à 9.\"],\"4EAgIb\":[\"Grille de sudoku vierge\"],\"4HAVnv\":[\"Chaque grille de ce recueil provient d’un corpus intégré que Suuudokuuu contrôle avec deux algorithmes de résolution indépendants, un solveur à couverture exacte de type Dancing Links et un solveur à masques de bits sur tableaux typés, avant de le livrer\xA0: chaque grille est ainsi confirmée comme n’ayant qu’une seule solution. Le corpus puise dans le catalogue de grilles à 17 chiffres du projet tdoku et dans la liste de grilles difficiles top1465 de magictour, et chaque grille est aussi résolue logiquement et cotée sur l’échelle SE au moment de l’empaquetage du corpus. Seules survivent les grilles dont l’étape la plus difficile est une chaîne forcée\u202F; tout ce qui cède à une chaîne, au coloriage ou à l’AIC est écarté, car ni le nombre de chiffres donnés ni la liste source ne suffiraient seuls à promettre une grille Enfer. Chaque survivante se résout encore sur notre échelle de techniques sans deviner\xA0: chaque grille ici est donc garantie soluble par la logique avant même que vous preniez un crayon.\"],\"4NMPvd\":[\"Quelles techniques faut-il connaître pour le sudoku Difficile\u202F?\"],\"4apI84\":[\"Sudoku en gros caractères à imprimer\"],\"52_TbA\":[\"Vérifier les fish et les wings sur papier\"],\"57DMl6\":[\"Les chaînes commencent à se mettre en place\u202F? Le <0>recueil de sudoku Enfer à imprimer</0> est le dernier niveau, où chaque grille exige une chaîne forcée. Revenez au <1>sudoku Difficile à imprimer</1> pour les fish et les wings uniquement, ou jouez à Cauchemar sur écran sur la <2>page Sudoku Cauchemar</2>.\"],\"5D6pgW\":[\"Une grille Facile issue du même générateur que l’application. Jouez-y ici même.\"],\"5EmtkG\":[\"Le PDF de sudoku Enfer à imprimer est-il gratuit\u202F?\"],\"5YPKNQ\":[\"Qui a coté ces grilles\u202F?\"],\"5a2b2H\":[\"Ce sont des grilles à 17 chiffres\u202F?\"],\"5jz4-5\":[\"Le sudoku gratuit en ligne, c’est jouer au classique casse-tête numérique de 9×9 dans un navigateur ou une application, sans achat, sans limite d’installation ni abonnement, et \",[\"SITE_NAME\"],\" en est une implémentation gratuite au code source disponible\xA0: sept niveaux de difficulté de Novice à Infini, des guides qui expliquent les techniques, sans publicité ni suivi dans le jeu. Jouez dans le navigateur ou installez l’application\u202F; votre progression, vos séries et vos statistiques restent sur l’appareil où vous jouez. Découvrez <0>pourquoi \",[\"SITE_NAME\"],\" est conçu ainsi</0> pour un argumentaire complet et vérifiable.\"],\"5tWoLs\":[\"Apprendre le sudoku\"],\"64gfbY\":[\"Jouer au sudoku Novice maintenant\"],\"6JHmjr\":[\"Oui. Chaque grille est contrôlée par un solveur à couverture exacte de type Dancing Links et par un solveur à masques de bits avant d’être livrée, et chacune a exactement une solution.\"],\"6Y2zqp\":[\"Le sudoku Moyen est-il difficile\u202F?\"],\"6i2Miv\":[\"Cauchemar ne compte que \",[\"clueCount\"],\" chiffres donnés, et c’est le recueil où la page imprimée justifie vraiment sa place. Chaque grille a été testée avec un solveur qui connaît déjà tous les fish et tous les wings, y compris le <0>swordfish</0> et le <1>XY-Wing</1>, et n’a été conservée que parce que ce solveur a bloqué. Ce qui les termine, c’est le raisonnement par chaînes, et une chaîne est bien plus facile à construire sur papier, où l’on peut crayonner les liens et les suivre, que sur un écran exigu. Notre échantillon de \",[\"sampleSize\"],\" grilles situe le niveau à SE \",[\"seRatingRange\"],\".\"],\"6mE7Xy\":[\"Une intersection ou une paire ne devient visible que lorsque vous voyez d’un coup d’œil tous les candidats restants d’une ligne, d’une colonne ou d’un bloc\u202F; c’est pourquoi le papier aide vraiment plus ici qu’un écran\xA0: notez de petits chiffres dans le coin de chaque case vide, puis parcourez une ligne à la recherche d’un chiffre piégé dans un seul bloc, ou de deux cases qui partagent exactement deux candidats. Aucun de ces motifs ne place un chiffre à lui seul, chacun ne fait que retirer des candidats\xA0: attendez-vous donc à marquer quelques éliminations avant qu’un nouveau singleton nu apparaisse vraiment. Travailler au crayon plutôt qu’au stylo permet d’effacer sans frais une mauvaise annotation.\"],\"6pYHox\":[\"<0>Novice.</0> Se résout avec de simples dernières cases libres et des singletons nus.\"],\"6tfEbk\":[\"Chaque grille est vérifiée par deux algorithmes de résolution indépendants pour s’assurer qu’elle n’a qu’une seule solution.\"],\"6yBCvI\":[\"Ce qui fait une grille Cauchemar\"],\"6z6usR\":[\"Vous voulez les grilles record sur papier\u202F? Téléchargez le <0>PDF de sudoku Infini à imprimer</0>. Pas encore prêt\u202F? Revenez au <1>Sudoku Enfer</1>, où chaque grille exige une chaîne forcée mais reste à la portée de notre échelle de techniques. Lisez l’histoire d’Everest et d’AI Escargot sur la page des <2>grilles de sudoku les plus difficiles</2>, comparez tous les niveaux sur la page <3>Niveaux de difficulté du sudoku</3>, ou retournez à l’<4>accueil</4>.\"],\"6zwJ5l\":[\"Facile se situe au bas de l’échelle SE (Sudoku Explainer), au même niveau que Novice\xA0: notre échantillon de \",[\"sampleSize\"],\" grilles se mesure à SE \",[\"seRatingRange\"],\". Les deux niveaux partagent une même plage parce que l’échelle SE évalue un singleton caché à 1.5, soit moins qu’un singleton nu à 2.3\xA0: la technique qui définit Facile coûte donc moins cher, sur cette échelle, que celle qui définit Novice. Ce qui change vraiment, c’est l’endroit où il faut regarder\xA0: un singleton nu se lit sur une seule case, un singleton caché sur une unité entière. Ce niveau convient aux joueurs qui ont terminé quelques grilles Novice et qui veulent une grille nettement plus longue à finir.\"],\"75Y3_I\":[\"AI Escargot figure-t-il dans le recueil à imprimer\u202F?\"],\"7A3Fmz\":[\"Niveau plus facile\"],\"7Y8jud\":[\"Jouer au sudoku Difficile maintenant\"],\"7Z44bB\":[\"Vous repérez les fish et les wings sans erreur\u202F? Passez au <0>recueil de sudoku Cauchemar à imprimer</0> pour les chaînes et le coloriage. Revenez au <1>sudoku Moyen à imprimer</1> pour les seules intersections et sous-ensembles, ou jouez à Difficile sur écran sur la <2>page Sudoku Difficile</2>.\"],\"7hktsm\":[\"Pour commencer\"],\"7lhqPv\":[\"En bref\"],\"7r6sCa\":[\"Taille du texte\"],\"83yMJR\":[\"Chaque niveau, de Novice à Infini, a désormais son propre guide, qui détaille ce qui sépare exactement un niveau du suivant\xA0: nombre de chiffres donnés, techniques requises et une évaluation honnête de la difficulté réelle de chacun. Commencez par la page <0>Niveaux de difficulté du sudoku</0>, ou voyez comment elle se compare aux <1>grilles les plus difficiles</1> jamais publiées.\"],\"8GGOmr\":[\"Une grille terminée satisfait les trois règles à la fois. C’est ce recoupement qui rend le sudoku soluble par la logique\xA0: un chiffre déjà exclu par sa ligne, sa colonne et son bloc n’a plus nulle part où aller, et c’est le fondement de presque toutes les techniques de résolution. Chaque technique nommée sur ce site, du singleton le plus simple à la plus longue chaîne, n’est au fond qu’une façon plus efficace de suivre ce recoupement sur de nombreuses cases à la fois plutôt qu’une case après l’autre.\"],\"8HgdwA\":[[\"mediumClueCount\"],\" chiffres donnés, avec la garantie de bloquer sur les singletons avant de céder aux intersections et aux sous-ensembles. Voir la <0>page Sudoku Moyen</0> pour y jouer en ligne.\"],\"8hKEc0\":[\"FAQ du sudoku Cauchemar\"],\"8j_b89\":[\"Cauchemar s’arrête à l’AIC\xA0: une grille qui y résiste dépasse ce que les niveaux générés vous proposent.\"],\"8ko6ZU\":[\"<0>Enfer</0>\xA0: la garantie de bloquer sur l’AIC et d’exiger une chaîne forcée, tirée d’un corpus intégré et vérifié plutôt que générée selon une plage de techniques.\"],\"8wCnRb\":[\"Les grilles sont imprimées exactement telles qu’elles ont été publiées, sans aucun mélange, afin que vous puissiez comparer votre grille aux originaux évoqués sur la page des <0>grilles de sudoku les plus difficiles</0>. Elles s’impriment \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" par page avec la place d’un jeu complet d’annotations au crayon, dont vous aurez besoin\xA0: à ce niveau, la plupart des joueurs gardent tous les candidats écrits et testent les chaînes sur une feuille à part. Les dernières pages contiennent les grilles terminées, de sorte que vous pouvez vérifier un long raisonnement sans avoir à le mener à terme.\"],\"92GEeo\":[\"Envie de vous échauffer d’abord\u202F? Le <0>recueil de sudoku Enfer à imprimer</0> contient des grilles à chaîne forcée, difficiles mais encore à la portée de notre échelle de techniques. Vous préférez un écran\u202F? Jouez aux mêmes grilles record sur la <1>page Sudoku Infini</1>, où chaque partie mélange la grille, ou parcourez tous les recueils sur la <2>page du sudoku à imprimer</2>.\"],\"93EF2k\":[\"Combien de chiffres donnés compte un sudoku Enfer\u202F?\"],\"9AexDe\":[\"Une grille qu’un solveur limité aux dernières cases libres et aux singletons nus peut terminer est rejetée\xA0: elle est trop facile pour ce niveau.\"],\"9COcEj\":[\"Fish\xA0: X-Wing, swordfish, jellyfish et leurs variantes finned et sashimi. Wings\xA0: XY-Wing, XYZ-Wing et W-Wing.\"],\"9TF92W\":[\"Notre échantillon de \",[\"sampleSize\"],\" grilles Facile se mesure à SE \",[\"seRatingRange\"],\".\"],\"9e_cYH\":[\"FAQ du sudoku Novice\"],\"9qTjdv\":[\"Combien de grilles contient le PDF de sudoku Moyen à imprimer\u202F?\"],\"9rfjS-\":[[\"PRINTABLE_LARGE_PRINT_PAGE_COUNT\"],\" pages\"],\"AKA0Xn\":[\"Quelles techniques ce recueil Difficile exige-t-il\u202F?\"],\"AUiKUx\":[\"Chaque grille a la garantie d’avoir une solution unique, et chaque niveau en dessous d’Infini se résout sans deviner\"],\"AV85q_\":[[\"clueCount\"],\" chiffres donnés sur 81 cases, résolus du début à la fin avec des dernières cases libres, des singletons nus et des singletons cachés.\"],\"AdsNQX\":[\"Oui. Notre échantillon situe Enfer à SE \",[\"hellSeRatingRange\"],\", et chaque grille Infini porte une cote publiée comprise entre \",[\"lowestRatingLabel\"],\" et \",[\"highestRatingLabel\"],\". Les grilles Enfer cèdent encore à notre échelle de techniques\u202F; les grilles Infini, non.\"],\"AfMtNM\":[\"FAQ du sudoku Enfer\"],\"Ak9Eh5\":[\"Une grille Difficile issue du même générateur que l’application. Jouez-y ici même.\"],\"B-pBHn\":[\"Enchaînement des niveaux de difficulté du sudoku\"],\"BJrGt8\":[\"Exactement une technique. Chaque grille Novice peut être terminée avec des dernières cases libres et des singletons nus\u202F; aucune grille Facile ne le peut, et chacune a besoin d’au moins un singleton caché pour sortir de l’impasse.\"],\"BZz12Q\":[\"Imprimer\"],\"C1_WBQ\":[\"Le sudoku est un casse-tête de logique qui se joue sur une grille de 9×9 divisée en neuf blocs de 3×3. Le but est de remplir chaque case vide avec un chiffre de 1 à 9 de sorte qu’aucun chiffre ne se répète dans une ligne, une colonne ou un bloc. Un sudoku bien formé démarre toujours avec certaines cases déjà remplies (les chiffres donnés, ou indices de départ) et a toujours exactement une solution valide, accessible par la seule logique, sans deviner.\"],\"C4kvBI\":[\"Notre échantillon de \",[\"sampleSize\"],\" grilles Enfer se mesure à SE \",[\"seRatingRange\"],\", avec le <0/> comme étape la plus difficile la plus fréquente.\"],\"CA7v0X\":[\"Certaines de ces grilles démarrent avec aussi peu que \",[\"HELL_CORPUS_MINIMUM_GIVEN_COUNT\"],\" chiffres donnés et semblent presque vides au premier regard\xA0: les \",[\"PRINTABLE_BOOKLET_SIZE\"],\" grilles s’impriment \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" par page avec une taille de case généreuse, précisément pour laisser la place de suivre les candidats à la main le long d’une longue chaîne. Les dernières pages contiennent les grilles terminées, ce qui est presque indispensable à ce niveau\xA0: vérifier une chaîne d’éliminations à l’œil est lent, et un corrigé imprimé permet de confirmer l’état final sans refaire tout le chemin.\"],\"CAD1qm\":[\"Une chaîne suit une suite alternée de liens forts et de liens faibles\xA0: on part d’un candidat et on avance jusqu’à prouver une élimination ou un placement, quelle que soit la branche qui s’avère vraie. La X-Chain travaille sur un seul chiffre\u202F; la XY-Chain suit plutôt un chemin de cases bivaluées. Le coloriage simple attribue deux couleurs alternées à un réseau de liens forts sur un chiffre et supprime tout candidat qui voit les deux couleurs, et l’AIC généralise toute la famille, en mélangeant chiffres et types de cases le long d’une même chaîne continue. Enfer commence là où tout cela s’épuise. Une chaîne forcée suppose un candidat, les possibilités d’une case ou les emplacements d’une unité, suit toutes les conséquences et ne retient que ce qui vaut dans chaque branche\u202F; les pages <0>Nishio</0>, <1>chaîne forcée de case</1> et <2>chaîne forcée de région</2> en détaillent un exemple chacune. Une grille n’entre dans le corpus Enfer que si son étape la plus difficile sur le chemin de cote optimale est une chaîne forcée, et seulement si notre échelle de techniques peut encore la terminer\xA0: aucune grille Enfer ne vous demande jamais de deviner.\"],\"CLPF0E\":[\"Les cotes sont les valeurs que publient des évaluateurs indépendants, et non nos propres mesures.\"],\"ChsZzh\":[[\"hardClueCount\"],\" chiffres donnés, avec la garantie de bloquer sur les sous-ensembles et de céder aux fish et aux wings. Voir la <0>page Sudoku Difficile</0> pour y jouer en ligne.\"],\"DE2rA9\":[\"Chiffres donnés et difficulté\"],\"DE6q1A\":[\"Oui, par construction. Cauchemar s’arrête à l’AIC, et aucune grille Enfer ne peut être résolue avec ce que Cauchemar autorise. Notre échantillon situe Enfer à SE \",[\"hellSeRatingRange\"],\" et Cauchemar à SE \",[\"nightmareSeRatingRange\"],\".\"],\"DFi0Zn\":[\"Plus difficile que tout le reste de l’application, et de loin. Notre échantillon de \",[\"sampleSize\"],\" grilles <0>Enfer</0> se mesure à SE \",[\"hellSeRatingRange\"],\"\u202F; Infini commence à \",[\"lowestRatingLabel\"],\". Les cotes d’Infini ne sont pas nos propres mesures. Le cotateur de Suuudokuuu n’évalue l’échelle SE que jusqu’aux chaînes et réseaux forcés et indique \",[\"SE_RATING_CEILING\"],\" avec un indicateur de plafond au-delà\u202F; pour ces grilles, nous citons donc les chiffres que publient des évaluateurs indépendants, comme l’explique le <1>guide de la cote de difficulté</1>.\"],\"DIr2XR\":[\"Intersections\xA0: paire pointée, triplet pointé, réduction bloc-ligne. Sous-ensembles\xA0: paire nue, paire cachée.\"],\"DRVEbn\":[\"FAQ du sudoku Enfer à imprimer\"],\"DRleO8\":[\"<0>Dernière case libre</0>\xA0: le coup le plus simple qui soit, remplir la dernière case vide d’une unité.\"],\"D_b_9m\":[\"FAQ du sudoku Facile\"],\"DgPHNt\":[\"Un quasi-fish\xA0: les lignes ou les colonnes s’alignent comme un X-Wing ou un <0>swordfish</0>, à l’exception d’un ou deux candidats supplémentaires, la nageoire (fin). L’élimination reste valable, mais seulement dans les cases que le fish et la nageoire voient toutes les deux.\"],\"DjGWF0\":[\"Notez au crayon tous les candidats restants des cases vides, puis parcourez l’index des techniques par ordre de difficulté pour continuer à les éliminer.\"],\"Drd4wO\":[\"Un chiffre limité à deux cases d’un même bloc, qui sont aussi sur la même ligne ou la même colonne. Il peut alors être effacé du reste de cette ligne ou de cette colonne, puisque l’une de ces deux cases doit le contenir.\"],\"DvhSrh\":[[\"clueCount\"],\" chiffres donnés sur 81 cases, avec la garantie d’avoir besoin d’un singleton caché, et de rien de plus difficile.\"],\"E5Cz6q\":[[\"PRINTABLE_BOOKLET_SIZE\"],\" grilles\"],\"ER15gL\":[\"Une grille record Infini issue du même ensemble sélectionné que l’application, mélangée. Jouez-y ici même.\"],\"ETZyJl\":[\"Sept niveaux de difficulté de Novice à Infini en passant par Enfer, le niveau supérieur proposant des grilles record comme Everest et AI Escargot\"],\"EYQUVy\":[\"<0>Difficile.</0> Bloque toujours sur les sous-ensembles et cède toujours à un fish ou à un wing.\"],\"EYVt4M\":[\"Très grande taille de texte\"],\"EyMkmB\":[\"Quel est le niveau de difficulté le plus facile au sudoku\u202F?\"],\"FfmJIb\":[\"Le PDF de sudoku Moyen à imprimer est-il gratuit\u202F?\"],\"Fgi0TQ\":[\"Aucune grille du recueil n’exige de fish, de wing ni de chaîne.\"],\"Fv02gG\":[\"Notre échantillon publié de \",[\"sampleSize\"],\" grilles Difficile situe le niveau à SE \",[\"seRatingRange\"],\", avec le <0/> comme étape la plus difficile la plus fréquente, des chiffres que le <1>guide de la cote de difficulté du sudoku</1> mesure directement plutôt que de les supposer. Les \",[\"PRINTABLE_BOOKLET_SIZE\"],\" grilles s’impriment ici \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" par page, avec la place de noter les candidats, et les grilles résolues des dernières pages vous permettent de confirmer qu’une élimination de fish était bien valable.\"],\"G70CkD\":[\"Combien de chiffres donnés compte un sudoku Moyen\u202F?\"],\"GCBW83\":[\"Résolvez d’abord les placements les moins coûteux\xA0: dernières cases libres, puis singletons nus, puis singletons cachés.\"],\"GOSVU9\":[\"Les grilles Moyen comptent \",[\"clueCount\"],\" chiffres donnés et ont la garantie de bloquer sur les singletons avant de céder à une intersection ou à un sous-ensemble.\"],\"GRoZ7D\":[\"Sudoku Enfer\"],\"GU9wm2\":[\"Puis-je les utiliser en classe\u202F?\"],\"G_3WRn\":[\"Est-ce que ça fonctionne hors ligne\u202F?\"],\"GalvXV\":[\"Infini est le niveau de Suuudokuuu qui va au-delà d’Enfer\xA0: un ensemble sélectionné des grilles de sudoku les plus difficiles jamais publiées, les grilles record dont la communauté des résolveurs débat encore, à jouer gratuitement. Chaque grille Infini est une grille connue, avec une cote Sudoku Explainer (SE) publiée d’au moins \",[\"minimumRatingLabel\"],\"\xA0: l’Everest d’Arto Inkala, Platinum Blonde, AI Escargot, Golden Nugget et \",[\"additionalPuzzleCount\"],\" autres, vérifiées comme n’ayant qu’une seule solution avant d’être livrées. Ce sont les grilles que décrit notre guide des <0>grilles de sudoku les plus difficiles</0>\u202F; Infini est l’endroit où vous y jouez.\"],\"GeGHUl\":[\"Chaque PDF est au format US Letter et dessiné avec des lignes et du texte vectoriels\xA0: il s’imprime nettement à toutes les tailles. Ouvrez le fichier et imprimez à 100\u202F% (et non en «\u202Fajustant à la page\u202F», ce qui peut déformer la grille sur certaines imprimantes), en recto seul si vous voulez garder les corrigés sur des feuilles séparées des grilles.\"],\"Gfmra_\":[\"Une grille Facile pour commencer. Jouez-y ici même, ou choisissez l’un des sept niveaux de difficulté dans l’application.\"],\"Gu8Ueq\":[\"Ce qui fait une grille Infini\"],\"GzaiWG\":[\"FAQ\xA0: comment jouer au sudoku\"],\"H47ltZ\":[\"Comment imprimer ces grilles\u202F?\"],\"HCMGUO\":[\"Faut-il parfois deviner\u202F?\"],\"HDn1fw\":[[\"clueCount\"],\" chiffres donnés sur 81 cases, avec la garantie d’avoir besoin d’au moins un fish ou un wing, au-delà de tous les sous-ensembles.\"],\"HJEQpI\":[\"Entre \",[\"HELL_CORPUS_MINIMUM_GIVEN_COUNT\"],\" et \",[\"HELL_CORPUS_MAXIMUM_GIVEN_COUNT\"],\". Enfer ne choisit pas ses grilles d’après le nombre de chiffres donnés\u202F; une grille est retenue parce qu’elle exige une chaîne forcée, quel que soit son nombre de chiffres de départ.\"],\"HPogd9\":[\"Pourquoi recommande-t-on le papier pour les grilles à chaînes\u202F?\"],\"HQCVxF\":[\"Novice est-il le bon niveau pour un enfant ou un premier essai\u202F?\"],\"HSXkrR\":[\"Une grille bien formée a toujours une solution et une seule, et n’oblige jamais à deviner.\"],\"HV3Yoi\":[\"Sudoku Difficile\"],\"Ht078b\":[\"Grille 1 du recueil Moyen, parmi les \",[\"PRINTABLE_BOOKLET_SIZE\"],\" du PDF.\"],\"I11j00\":[\"Cauchemar est le niveau expert de Suuudokuuu, ce que la plupart des autres applications appelleraient très difficile ou expert. Une grille Cauchemar ne compte que \",[\"clueCount\"],\" chiffres donnés sur 81 cases, et c’est le niveau où les motifs bornés ne suffisent plus\xA0: chaque grille a été confrontée à un solveur qui connaît déjà tous les fish et tous les wings jusqu’au <0>W-Wing</0>, et n’est étiquetée Cauchemar que parce que ce solveur a bloqué. Pour en venir à bout, il faut un raisonnement par chaînes\xA0: <1>X-Chain</1>, <2>XY-Chain</2>, <3>coloriage simple</3> et <4>AIC</4>, la chaîne d’inférences alternées qui généralise les trois autres.\"],\"I3XIAf\":[\"Vous préférez un écran\u202F? Jouez à Suuudokuuu maintenant\"],\"IANVSf\":[\"Non. Il n’y a aucune publicité nulle part et aucun suivi dans le jeu\u202F; ce site n’utilise que des statistiques de pages anonymes et sans cookie.\"],\"IB9N-i\":[\"Quelle différence y a-t-il entre un chiffre donné et un candidat\u202F?\"],\"IFKUNe\":[\"Aucune note au crayon, aucune logique d’élimination et aucune devinette ne sont nécessaires pour aucune grille du recueil.\"],\"IOgWqm\":[\"Chargement de la grille…\"],\"IjDWTu\":[\"Comment les grilles sont vérifiées\"],\"IlAsp5\":[\"Par quel niveau de sudoku commencer\u202F?\"],\"IqBsZ0\":[\"Oui. Le PDF se télécharge gratuitement, sans compte et sans filigrane, et comprend un corrigé complet pour chaque grille.\"],\"IrAE3z\":[\"Solveur\"],\"Iu83qB\":[\"Grille 1 du recueil Novice, parmi les \",[\"PRINTABLE_BOOKLET_SIZE\"],\" du PDF.\"],\"JBdo3D\":[\"FAQ sur les niveaux de difficulté du sudoku\"],\"JJoC7U\":[\"Ce qui fait une grille Difficile\"],\"Jrqsp5\":[\"La difficulté vient ici de la technique que chaque grille exige, pas du nombre de chiffres donnés.\"],\"JrrSQM\":[\"Quelle différence y a-t-il entre le sudoku Novice et le sudoku Facile\u202F?\"],\"Jry7J2\":[\"Une grille Novice issue du même générateur que l’application. Jouez-y ici même.\"],\"KDXdKh\":[\"Une grille Cauchemar issue du même générateur que l’application. Jouez-y ici même.\"],\"KPuUq2\":[\"Notez les candidats quand les cases faciles sont épuisées\"],\"KQe27c\":[\"Les corrigés sont-ils inclus\u202F?\"],\"KVC9CP\":[\"Le recueil de sudoku Novice à imprimer est un PDF gratuit de grilles à \",[\"clueCount\"],\" chiffres donnés dont chaque case vide se résout par une dernière case libre ou un singleton nu, une propriété vérifiée pour chaque grille avant son entrée dans le PDF. C’est le recueil à confier à un premier joueur, à une classe qui découvre les règles, ou à quiconque veut une grille qui n’oblige jamais à un second essai.\"],\"KiwVTj\":[\"Suuudokuuu propose-t-il une version en gros caractères de ce recueil\u202F?\"],\"L0XezG\":[\"Ce qui fait une grille Enfer\"],\"L3TeBG\":[\"Quelle est la difficulté du sudoku Novice\u202F?\"],\"LBVuWJ\":[\"Sudoku Novice\"],\"LDOq68\":[\"Combien de grilles contient le PDF de sudoku Cauchemar à imprimer\u202F?\"],\"LI4SwS\":[\"Ce qui fait une grille Moyen\"],\"LNoRL7\":[\"<0>Facile.</0> Ajoute les singletons cachés, sans avoir besoin de noter les candidats.\"],\"LfQJwZ\":[\"Une page de couverture indique d’emblée le nombre de grilles et de pages, puis les \",[\"PRINTABLE_BOOKLET_SIZE\"],\" grilles s’impriment \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" par page, de sorte qu’une seule feuille contient \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" grilles complètes. Les dernières pages présentent chaque grille résolue avec la même mise en page, si bien que vérifier une réponse n’oblige jamais à chercher dans un autre format. Le fichier entier n’utilise que des graphiques vectoriels et une police PDF standard\xA0: il s’imprime proprement à toutes les tailles que prend en charge une imprimante. Notre échantillon publié de \",[\"sampleSize\"],\" grilles Facile se situe à SE \",[\"seRatingRange\"],\", des chiffres que le <0>guide de la cote de difficulté du sudoku</0> mesure directement plutôt que de les supposer.\"],\"LrHydF\":[\"Lisez le <0>guide pour apprendre à jouer</0> pour les trois règles et un pas-à-pas de vos premiers coups, ou cherchez un terme dans le <1>glossaire du sudoku</1>, qui définit chaque technique et chaque mot de vocabulaire employé dans les guides.\"],\"Lxq-zS\":[\"Sudoku en gros caractères\"],\"M1Yfw6\":[\"Au moins un <0>singleton caché</0> par grille, en plus des dernières cases libres et des singletons nus que Novice utilise déjà, et rien de plus difficile.\"],\"MLFx1h\":[\"Oui. Facile est le niveau source du PDF en gros caractères, avec un échantillon de \",[\"PRINTABLE_LARGE_PRINT_SIZE\"],\" grilles aux cases plus grandes pour ceux qui veulent plus de place pour écrire.\"],\"MREaAq\":[\"Tout ce dont Moyen a besoin, plus au moins un fish ou un wing\xA0: X-Wing, swordfish, jellyfish, leurs variantes finned et sashimi, XY-Wing, XYZ-Wing ou W-Wing. L’un d’eux est toujours requis, car une grille qui n’en demande aucun est classée Moyen.\"],\"MVYMfh\":[\"Difficultés du sudoku\"],\"M_zq3f\":[\"FAQ du sudoku Infini à imprimer\"],\"Mz7rRO\":[\"Cherchez une unité dont huit cases sur neuf sont déjà remplies, et placez le chiffre manquant dans la case vide.\"],\"N0hmpU\":[[\"clueCount\"],\" chiffres donnés sur 81 cases, un seul de moins qu’en Moyen, et c’est précisément pourquoi ce niveau se définit par les techniques qu’il exige plutôt que par le nombre de chiffres donnés.\"],\"NQTfla\":[\"FAQ du sudoku Novice à imprimer\"],\"NeWjyh\":[\"<0>Novice</0>\xA0: \",[\"newbieClueCount\"],\" chiffres donnés, résolus avec de simples dernières cases libres et des singletons nus.\"],\"NkdmkS\":[\"Quelles techniques ce recueil Cauchemar exige-t-il\u202F?\"],\"Nq65SI\":[\"Non. Le nombre de chiffres donnés et la difficulté sont deux choses distinctes\u202F; voir le <0>guide du sudoku à 17 chiffres</0>. Ces grilles sont difficiles parce que chacune exige une chaîne forcée, pas à cause du nombre de chiffres de départ.\"],\"NuoZju\":[\"Une grille Enfer terminée et vous en voulez encore\u202F? <0>Sudoku Infini</0> propose les grilles record (Everest, Platinum Blonde, AI Escargot), qui dépassent même nos chaînes forcées. Pas encore prêt pour les chaînes\u202F? Revenez au <1>Sudoku Cauchemar</1>, qui demande le même raisonnement avec une plus grande part de la grille déjà remplie. Vous préférez le papier\u202F? Téléchargez le <2>PDF de sudoku Enfer à imprimer</2>. Parcourez l’<3>index des techniques</3>, en particulier X-Chain, XY-Chain, coloriage simple et AIC, le <4>guide pour apprendre à jouer</4>, le <5>guide du sudoku à 17 chiffres</5>, tous les niveaux sur la page <6>Niveaux de difficulté du sudoku</6>, ou retournez à l’<7>accueil</7>.\"],\"Nyd-0x\":[\"Combien de chiffres donnés compte un sudoku Difficile\u202F?\"],\"NzFVBG\":[\"En quoi un fish ou un wing est-il plus facile à vérifier sur papier\u202F?\"],\"OMs2n2\":[\"Prêt à enchaîner les éliminations plutôt qu’à repérer des formes\u202F? Passez au <0>Sudoku Cauchemar</0>, ou revenez au <1>Sudoku Moyen</1> pour une grille d’intersections et de sous-ensembles. Vous préférez le papier\u202F? Téléchargez le <2>PDF de sudoku Difficile à imprimer</2>. Consultez l’<3>index des techniques</3>, le <4>guide pour apprendre à jouer</4>, tous les niveaux sur la page <5>Niveaux de difficulté du sudoku</5>, ou retournez à l’<6>accueil</6>.\"],\"OubwsB\":[\"Combien de grilles contient le PDF de sudoku Novice à imprimer\u202F?\"],\"P2bU2d\":[\"Ce qui fait une grille Facile\"],\"P6JVwt\":[\"Rarement. La plupart des joueurs peuvent suivre de tête les quelques candidats dont un singleton caché a besoin, mais les écrire ne fait jamais de mal sur une ligne plus chargée.\"],\"PDbaU0\":[\"Faut-il noter des candidats pour les grilles Novice\u202F?\"],\"PFKt-9\":[\"Difficile descend à \",[\"clueCount\"],\" chiffres donnés, et c’est le premier recueil imprimable du site où les sous-ensembles seuls ne suffisent pas à aller jusqu’au bout. Chaque grille a été testée avec un solveur qui connaît déjà toutes les intersections et tous les sous-ensembles, et n’a été conservée que parce que ce solveur a bloqué. Ce qui les termine, c’est un fish ou un wing\xA0: le <0>X-Wing</0> et ses variantes plus grandes et finned, ou l’un des wings bivalués.\"],\"PGxh1d\":[\"Qu’est-ce qu’un fish finned au sudoku\u202F?\"],\"PKS4Or\":[\"Le PDF de sudoku Infini à imprimer est-il gratuit\u202F?\"],\"PYziuK\":[\"Une chaîne n’a pas de forme fixe et se construit lien après lien, ce qui est bien plus facile à suivre en notant chaque lien fort et faible qu’en faisant défiler un petit écran.\"],\"PZQD8F\":[\"Jouer maintenant\"],\"Pbm-BS\":[\"Comment Suuudokuuu garantit-il la technique exigée par un niveau\u202F?\"],\"PdMLK1\":[\"L’Everest d’Arto Inkala (2012), 21 chiffres donnés, publié à SE 11.9.\"],\"Pg0uLs\":[\"Tous les niveaux sont gratuits, sans publicité ni inscription. <0>Jouez une grille maintenant</0> à l’un des sept niveaux, ou consultez le détail complet des chiffres donnés et des techniques requises sur la page <1>Niveaux de difficulté du sudoku</1>. Vous apprenez sur papier\u202F? Commencez par le <2>PDF de sudoku Novice à imprimer</2>.\"],\"PgRaz8\":[\"Jouer au sudoku Facile maintenant\"],\"PivQ2i\":[\"Très. Chaque grille de l’ensemble Infini a une cote SE publiée d’au moins \",[\"lowestRatingLabel\"],\", bien au-delà de tout ce que produisent les niveaux générés ou le corpus Enfer. Notre propre cotateur cesse d’évaluer l’échelle SE à \",[\"SE_RATING_CEILING\"],\", les chiffres cités ici viennent donc d’évaluateurs indépendants, et notre moteur de techniques ne peut terminer seul aucune de ces grilles. Attendez-vous à avoir besoin de longues chaînes forcées et de réseaux forcés, et à ce qu’une seule grille prenne bien plus de temps que n’importe quoi d’autre sur ce site.\"],\"Pqhtap\":[\"Facile\"],\"PrxlWP\":[\"FAQ du sudoku Facile à imprimer\"],\"PszyWW\":[\"Quelle est la façon la plus rapide de progresser au sudoku\u202F?\"],\"PzS0uu\":[\"Les grilles Difficile comptent \",[\"clueCount\"],\" chiffres donnés et ont la garantie de demander au moins un fish ou un wing, au-delà de tous les sous-ensembles.\"],\"Q5B0cW\":[\"Enfer\"],\"QBE_L9\":[\"<0>Cauchemar.</0> Bloque toujours sur les fish et les wings et cède toujours à la logique des chaînes ou du coloriage.\"],\"QmRavQ\":[\"Non. Le mode notes d’une application suit les candidats à votre place et les met à jour automatiquement à mesure que vous placez des chiffres, et l’annulation retire une erreur sans rien effacer.\"],\"Qo4hE6\":[\"Une chaîne suit une suite alternée de liens forts et de liens faibles entre candidats\xA0: on part d’une extrémité et on raisonne vers l’autre jusqu’à ce que les deux bouts prouvent une élimination, quelle que soit l’hypothèse qui s’avère vraie. La X-Chain le fait sur un seul chiffre\u202F; la XY-Chain parcourt plutôt un chemin de cases bivaluées, en changeant de chiffre à chaque étape. Le coloriage simple attribue deux couleurs alternées à un réseau de liens forts sur un chiffre et supprime tout candidat qui voit les deux couleurs. L’AIC réunit toutes ces techniques en une seule, en mélangeant chiffres et types de liens le long d’une même chaîne continue. La différence avec un fish ou un wing n’est pas une question de subtilité mais de forme\xA0: un wing est une configuration fixe de trois ou quatre cases que l’on apprend à reconnaître, alors qu’une chaîne n’a pas de taille fixe et se construit coup après coup. Cauchemar s’arrête à l’AIC\xA0: tout ce qui résiste encore dépasse ce que les niveaux générés vous proposent.\"],\"R1g33v\":[\"Pas de grille, juste le quadrillage\xA0: une grille de 9×9 pleine page pour recopier une grille d’un livre ou d’un journal, plus une seconde page de quatre petites grilles pour des feuilles d’entraînement rapides. Utile aux enseignants qui préparent leurs propres fiches, ou à quiconque retranscrit une grille trouvée quelque part sans version imprimable.\"],\"RJUjbN\":[\"Conseils pour résoudre avec des annotations au crayon\"],\"RMq7iB\":[\"Un fish examine un seul chiffre sur plusieurs lignes à la fois. Le X-Wing est le plus petit\xA0: un chiffre limité aux deux mêmes colonnes sur deux lignes peut être effacé du reste de ces colonnes, car quelle que soit la ligne qui le contient, les colonnes sont déjà déterminées. Un <0>swordfish</0> étend la même idée à trois lignes, et un jellyfish à quatre. Les variantes finned et sashimi assouplissent le motif de base en autorisant un candidat supplémentaire qui permet encore une élimination plus restreinte mais sûre une fois pris en compte, et dans notre échantillon elles se déclenchent bien plus souvent que les formes classiques. Les wings fonctionnent autrement\xA0: un XY-Wing relie trois cases bivaluées de sorte qu’un candidat partagé par deux d’entre elles peut être effacé partout où les deux le voient, le XYZ-Wing donne aussi ce candidat au pivot, et le W-Wing relie deux cases bivaluées identiques par un lien fort sur un chiffre commun. Difficile s’arrête au W-Wing\xA0: une grille qui ne bouge toujours pas après avoir essayé tous les fish et tous les wings est une grille Cauchemar, pas une grille Difficile.\"],\"RRGDQM\":[\"Novice est le plus facile des sept niveaux de Suuudokuuu, suivi de Facile, Moyen, Difficile, Cauchemar, Enfer et Infini, par ordre croissant de difficulté.\"],\"Rj2Y_n\":[\"Les grilles Infinity les plus célèbres ont leur propre page, chacune jouable, imprimable et résolue pas à pas par le moteur : <0>AI Escargot</0>, <1>Golden Nugget</1>, <2>Platinum Blonde</2>, <3>Everest</3>, <4>Kolk</4> et <5>Silver Plate</5>.\"],\"Rwv4vE\":[\"Une chaîne forcée, sur chaque grille, ajoutée par-dessus les chaînes, le coloriage, les fish, les wings et les sous-ensembles que les niveaux précédents exigent déjà. La X-Chain, la XY-Chain, le coloriage simple et l’AIC vous mèneront loin, mais jamais jusqu’au bout\u202F; une <0>chaîne forcée Nishio</0> est le moyen habituel de sortir de l’impasse.\"],\"SPFeoH\":[\"FAQ du sudoku Difficile à imprimer\"],\"ScJ9fj\":[\"Politique de confidentialité\"],\"Sg-BY5\":[\"Le nombre de chiffres donnés n’est pas la difficulté. Ce n’est que le point de départ\xA0: moins il y a de chiffres de départ, moins il y a de placements immédiats, ce qui oblige le solveur, humain ou machine, à recourir à un éventail plus large de techniques nommées avant que la grille ne progresse de nouveau. Suuudokuuu retire des chiffres d’une grille résolue jusqu’à une cible propre à chaque niveau, vérifie que le résultat n’a toujours qu’une seule solution, puis fait ce qui définit vraiment le niveau\xA0: il résout la grille deux fois, une fois avec l’échelle de techniques du niveau inférieur et une fois avec la sienne, et ne garde la grille que si la première résolution échoue et la seconde réussit. Les grilles qui ratent le test sont écartées et une nouvelle est générée. C’est pourquoi chaque niveau ci-dessus est présenté comme une garantie plutôt qu’un espoir. L’<0>index complet des techniques</0> recense chaque motif de cette échelle, dans l’ordre où un solveur les essaie. Au sein d’une même plage, deux grilles peuvent encore différer beaucoup\xA0: <1>chiffres donnés et difficulté</1> mesure précisément l’ampleur de cet écart.\"],\"Sjq7vw\":[\"Pour chaque case vide restante, excluez tous les chiffres déjà utilisés dans sa ligne, sa colonne et son bloc. S’il ne reste qu’un seul chiffre, placez-le.\"],\"T5khAF\":[\"Jouer au sudoku Enfer maintenant\"],\"T91vKp\":[\"Jouer\"],\"TW-b-m\":[\"Non. Le nombre de chiffres donnés n’est que le point de départ qui pousse un solveur vers un éventail plus large de techniques\u202F; c’est la plage de techniques vérifiée par le générateur qui définit réellement chaque niveau. Le <0>guide chiffres donnés et difficulté</0> mesure directement cet écart.\"],\"T_JQXy\":[\"Notre échantillon de \",[\"sampleSize\"],\" grilles Moyen se mesure à SE \",[\"seRatingRange\"],\".\"],\"T_R-Qz\":[\"Principale\"],\"TiHBaL\":[\"Le sudoku Difficile est un niveau qui commence à \",[\"clueCount\"],\" chiffres donnés sur 81 cases et se définit par ce qu’un solveur limité aux sous-ensembles ne peut pas terminer\xA0: chaque grille du niveau a été passée dans un solveur équipé de toutes les intersections et de tous les sous-ensembles jusqu’au <0>quadruplet caché</0>, et n’a été conservée que parce que ce solveur est resté bloqué. Ce qui sort de l’impasse, c’est un fish (<1>X-Wing</1>, <2>swordfish</2>, <3>jellyfish</3> et leurs variantes <4>finned</4> et <5>sashimi</5>) ou un wing\xA0: <6>XY-Wing</6>, <7>XYZ-Wing</7> et <8>W-Wing</8>.\"],\"TqC0fH\":[[\"clueCount\"],\" chiffres donnés sur 81 cases, et chaque case vide se résout par une dernière case libre ou un singleton nu.\"],\"U1U2tC\":[\"Combien de chiffres donnés compte un sudoku facile\u202F?\"],\"U2AKxD\":[\"FAQ du sudoku à imprimer\"],\"U9wBFD\":[\"Facile reste dans une logique de singletons uniquement, il convient donc toujours aux débutants. La seule compétence ajoutée par rapport à Novice est de repérer un chiffre qui ne tient nulle part ailleurs dans une unité.\"],\"UF5_iX\":[\"Taille de texte par défaut\"],\"UILsns\":[\"N’écrivez des candidats dans une case que lorsque le balayage ne produit plus de placements.\"],\"Umo747\":[\"Aucune note au crayon, aucune logique d’élimination et aucune devinette ne sont jamais nécessaires.\"],\"Uq9L94\":[[\"clueCount\"],\" chiffres donnés sur 81 cases, bien moins d’un tiers de la grille.\"],\"UveQZj\":[\"Notre échantillon de \",[\"sampleSize\"],\" grilles Cauchemar se mesure à SE (Sudoku Explainer) \",[\"seRatingRange\"],\", avec le <0/> comme étape la plus difficile la plus fréquente. L’AIC est ici le plafond\xA0: chaque grille Cauchemar y cède, et le <1>niveau Enfer</1> commence exactement là où elle s’arrête, avec des grilles qui exigent une chaîne forcée. Certaines de ces grilles Enfer comptent plus de chiffres donnés que Cauchemar, ce qui est la preuve la plus nette sur le site que le nombre de chiffres donnés et la difficulté sont deux choses distinctes. Les tableaux mesurés se trouvent dans notre <2>guide de la cote de difficulté du sudoku</2>. Qualitativement, c’est ici que la difficulté cesse d’être une question de vitesse pour devenir celle de garder en tête toute une ligne d’implications sans en perdre le fil.\"],\"V9j1Oq\":[\"Non. Chaque grille du niveau est vérifiée comme soluble par l’échelle de techniques jusqu’à l’AIC avant d’être livrée, donc une chaîne aboutie existe toujours\u202F; le travail consiste à la trouver.\"],\"VHv3Qz\":[\"Les grilles Infini comptent de \",[\"INFINITY_MINIMUM_GIVEN_COUNT\"],\" à \",[\"INFINITY_MAXIMUM_GIVEN_COUNT\"],\" chiffres donnés et sont vérifiées par deux algorithmes de résolution indépendants pour s’assurer qu’elles n’ont qu’une seule solution.\"],\"VT7jaN\":[\"Une grille Enfer issue du même corpus vérifié que l’application. Jouez-y ici même.\"],\"VUJcE0\":[\"Oui. Chaque grille du recueil se résout avec une simple dernière case libre ou un singleton nu, aucune annotation de candidats ni logique d’élimination n’est donc jamais requise.\"],\"Vmq46x\":[\"Quand les dernières cases libres et les singletons nus deviennent automatiques, passez au <0>recueil de sudoku Facile à imprimer</0>, qui ajoute exactement une technique\xA0: le singleton caché. Pour jouer aux grilles Novice sur écran, rendez-vous sur la <1>page Sudoku Novice</1>. Pour l’échelle complète des techniques et les données mesurées derrière ces affirmations, consultez l’<2>index des techniques</2> et le <3>guide de la cote de difficulté du sudoku</3>.\"],\"VpuNLI\":[\"Gratuit, code source disponible sous licence \",[\"SITE_LICENSE\"],\". Sans publicité, sans compte, sans suivi dans le jeu\xA0: lisez <0>pourquoi</0> ou parcourez le <1>code source complet sur GitHub</1>. Apple et le logo Apple sont des marques d’Apple Inc., déposées aux États-Unis et dans d’autres pays. App Store est une marque de service d’Apple Inc. Google Play et le logo Google Play sont des marques de Google LLC.\"],\"W1nEnp\":[[\"clueCount\"],\" chiffres donnés sur 81 cases\xA0: un tiers de la grille est déjà rempli avant même de commencer.\"],\"W8o5ac\":[\"Les autres niveaux se définissent par les techniques qu’ils exigent. Infini se définit par sa réputation, mesurée\xA0: une grille n’est retenue que si des évaluateurs indépendants ont publié pour elle une cote SE de \",[\"minimumRatingLabel\"],\" ou plus. La plupart des \",[\"infinityCorpusSize\"],\" grilles proviennent d’un instantané de 2011 de la base de données de grilles difficiles que tient la communauté des résolveurs de sudoku\u202F; les autres sont les classiques nommés, repris des fils de forum et des publications où ils sont apparus pour la première fois. Avant que l’ensemble ne soit intégré à l’application, un solveur à couverture exacte de type Dancing Links et un solveur à masques de bits confirment tous deux que chaque grille a exactement une solution.\"],\"W9xBMf\":[\"Les nouveaux joueurs devraient commencer à Novice et monter d’un niveau à la fois\u202F; chaque étape ajoute exactement une nouvelle technique par rapport au niveau précédent, jusqu’à Difficile. Consultez d’abord le <0>guide pour apprendre à jouer</0> si les trois règles de base vous sont encore peu familières.\"],\"WB-pGD\":[\"Ce recueil imprime \",[\"PRINTABLE_BOOKLET_SIZE\"],\" des grilles de sudoku les plus difficiles jamais publiées, tirées du niveau Infini de Suuudokuuu\xA0: l’Everest d’Arto Inkala, AI Escargot, Platinum Blonde, Golden Nugget et d’autres grilles record, chacune avec une cote SE (Sudoku Explainer) publiée comprise entre \",[\"lowestRatingLabel\"],\" et \",[\"highestRatingLabel\"],\". Chacune a exactement une solution, et les grilles résolues se trouvent à la fin.\"],\"WG8Ftb\":[\"Combien de chiffres donnés compte une grille Novice\u202F?\"],\"WTwN7-\":[\"Jouer à \",[\"SITE_NAME\"]],\"WmW-Gm\":[\"La place disponible à l’impression compte plus ici qu’aux niveaux plus faciles, car les intersections et les paires reposent sur l’annotation des candidats dans les marges. Les \",[\"PRINTABLE_BOOKLET_SIZE\"],\" grilles s’impriment \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" par page à pleine taille de case, ce qui laisse assez de place autour de chaque chiffre pour noter au crayon les petits chiffres sur lesquels raisonne une intersection ou une paire. Les grilles résolues terminent le fichier afin que vous puissiez comparer vos annotations à une réponse confirmée. Notre échantillon publié de \",[\"sampleSize\"],\" grilles Moyen se mesure à SE \",[\"seRatingRange\"],\", des chiffres que le <0>guide de la cote de difficulté du sudoku</0> mesure directement plutôt que de les supposer.\"],\"WqP4CN\":[\"Oui, dans les applications iOS et Android. Une fois installé, \",[\"SITE_NAME\"],\" génère et résout les grilles entièrement sur votre appareil, et fonctionne donc de la même façon sans connexion.\"],\"WrhTzj\":[\"Oui. Chaque recueil de difficulté et le jeu en gros caractères comportent les grilles entièrement résolues sur les dernières pages, générées par le même solveur qui vérifie que chaque grille a exactement une solution avant d’être livrée.\"],\"WwMVff\":[\"Quelle est la difficulté du sudoku Cauchemar\u202F?\"],\"XGVJW3\":[\"Glossaire du sudoku\"],\"XORYRH\":[\"Les \",[\"PRINTABLE_BOOKLET_SIZE\"],\" grilles s’impriment \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" par page, à une taille telle qu’une chaîne qui traverse toute la grille tient encore confortablement sur une seule feuille. Des grilles entièrement résolues terminent le recueil, ce qui compte plus ici qu’aux niveaux plus faciles\xA0: une seule élimination manquée au milieu d’une chaîne se répercute vite, et un corrigé imprimé permet de la rattraper. La répartition mesurée derrière ces affirmations se trouve dans le <0>guide de la cote de difficulté du sudoku</0>.\"],\"XpU6Tm\":[\"Pourquoi Enfer utilise-t-il un corpus fixe plutôt que de générer des grilles\u202F?\"],\"XzG50N\":[\"Enfer est le niveau gradué par techniques le plus difficile de Suuudokuuu, ce que la plupart des concurrents appellent «\u202Fdiabolique\u202F» ou «\u202Fextrême\u202F». Une grille Enfer se définit par le raisonnement qu’elle exige, non par le petit nombre de chiffres de départ\xA0: aucune grille Enfer ne peut être terminée avec une technique que Cauchemar autorise, donc chacune exige une chaîne forcée. Contrairement aux niveaux générés, Enfer puise dans un corpus intégré de grilles difficiles publiées, vérifiées par deux solveurs indépendants avant d’être livrées, et chaque grille se résout encore sur notre échelle de techniques sans deviner. Attendez-vous à épuiser d’abord tous les motifs de chaîne et de coloriage (<0>X-Chain</0>, <1>XY-Chain</1>, <2>coloriage simple</2> et <3>AIC</3>) avant qu’une chaîne forcée ne fasse sauter le verrou.\"],\"Y3fLpk\":[\"Combien de grilles contient le PDF de sudoku Difficile à imprimer\u202F?\"],\"YCRno6\":[\"Gratuit, code source disponible, sans publicité\"],\"YGCzAJ\":[\"Chaque grille candidate est résolue deux fois\xA0: une fois avec l’échelle de techniques du niveau inférieur, qui doit échouer, et une fois avec la sienne, qui doit réussir. Les grilles qui ratent l’un ou l’autre test sont écartées et régénérées.\"],\"YM-Le2\":[[\"clueCount\"],\" chiffres donnés sur 81 cases, avec la garantie d’avoir besoin d’au moins une technique de chaîne ou de coloriage, au-delà de tous les fish et wings.\"],\"Y_LLdr\":[\"Le PDF de sudoku Facile à imprimer est-il gratuit\u202F?\"],\"Yj1j4Z\":[\"Grille 1 du recueil Enfer, parmi les \",[\"PRINTABLE_BOOKLET_SIZE\"],\" du PDF.\"],\"YjxNca\":[\"Jouer au sudoku Infini maintenant\"],\"Z-7bqV\":[\"FAQ du sudoku Difficile\"],\"Z9Mfy1\":[\"Que contient le recueil\"],\"Z9MhMF\":[\"Ce qui fait une grille Novice\"],\"ZBT6Lr\":[[\"infinityCorpusSize\"],\" grilles record de \",[\"INFINITY_MINIMUM_GIVEN_COUNT\"],\" à \",[\"INFINITY_MAXIMUM_GIVEN_COUNT\"],\" chiffres donnés, publiées avec une cote SE de \",[\"lowestRatingLabel\"],\" à \",[\"highestRatingLabel\"],\".\"],\"ZPXer3\":[\"Notes et candidats\"],\"Zm7CE_\":[\"Chaque technique que \",[\"SITE_NAME\"],\" utilise pour générer des indices est documentée avec une grille d’exemple détaillée tirée directement du moteur de résolution. Commencez par l’<0>index complet des techniques</0>, ou plongez dans l’un des premiers motifs que la plupart des joueurs apprennent.\"],\"ZtZST0\":[\"Chaque grille exige une chaîne forcée et est tirée de notre corpus Enfer intégré et vérifié. Voir la <0>page Sudoku Enfer</0> pour y jouer en ligne.\"],\"_4AR-Z\":[[\"PRINTABLE_BOOKLET_PAGE_COUNT\"],\" pages\"],\"_YA7YX\":[\"Oui, ainsi qu’Everest, Platinum Blonde et Golden Nugget. Le recueil imprime les grilles telles qu’elles ont été publiées à l’origine.\"],\"_kK7k_\":[\"Quelle différence y a-t-il entre un wing et une chaîne\u202F?\"],\"_nkVQD\":[\"Aucune grille du recueil n’exige de chaîne\xA0: cela ne commence qu’au niveau Cauchemar.\"],\"_t9fa1\":[\"Qu’est-ce que le sudoku Infini\u202F?\"],\"a3pVqb\":[\"Questions fréquentes\"],\"aF08Xt\":[\"Sept. Novice, Facile, Moyen, Difficile, Cauchemar et Enfer forment l’échelle de techniques, chaque niveau étant défini par un nombre de chiffres donnés et une plage de techniques garantie, et non par une étiquette marketing. Infini se place au-dessus\xA0: un ensemble sélectionné de grilles record choisies d’après leur cote publiée.\"],\"aIDRsS\":[\"<0>Moyen.</0> Bloque toujours sur les singletons et cède toujours aux intersections et aux sous-ensembles\xA0: paires pointées, réduction bloc-ligne, paires, triplets et quadruplets nus et cachés.\"],\"aMv0h8\":[\"Une grille Moyen issue du même générateur que l’application. Jouez-y ici même.\"],\"aOHWJD\":[\"<0>Singleton nu</0>\xA0: une case qui n’a plus qu’un seul candidat.\"],\"aQ3vvP\":[[\"nightmareClueCount\"],\" chiffres donnés, avec la garantie de bloquer sur les wings avant de céder aux chaînes et au coloriage. Voir la <0>page Sudoku Cauchemar</0> pour y jouer en ligne.\"],\"agPptk\":[\"Moyen\"],\"ajKnoT\":[\"Les trois règles du sudoku\"],\"alOHPr\":[\"Prêt à ce que les intersections et les sous-ensembles comptent\u202F? Passez au <0>recueil de sudoku Moyen à imprimer</0>, ou revenez au <1>sudoku Novice à imprimer</1> pour une grille encore plus douce. Pour jouer aux grilles Facile sur écran, rendez-vous sur la <2>page Sudoku Facile</2>.\"],\"bBobfF\":[\"Oui. Ce site n’impose aucune restriction à l’impression ni à la redistribution des PDF, y compris pour les distribuer en classe, lors d’un cours particulier ou dans un lot de fiches.\"],\"bIMckF\":[\"Le PDF standard adopte déjà une mise en page généreuse de \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" grilles par page. Pour des cases plus grandes en particulier, voir le <0>recueil de sudoku Facile à imprimer</0>, qui est aussi le niveau source de notre PDF en gros caractères.\"],\"bJo3n2\":[\"Astuces de sudoku\"],\"bLowF0\":[\"Résoudre vos premières cases\"],\"bMqX8c\":[\"Repérer les unités incomplètes\"],\"bQP2nt\":[\"Vous résolvez des grilles Facile sans recourir à un singleton caché\u202F? Revenez au <0>Sudoku Novice</0>, ou passez au <1>Sudoku Moyen</1>, où apparaissent les intersections et vos premières paires. Vous préférez le papier\u202F? Téléchargez le <2>recueil de sudoku Facile à imprimer</2>, ou consultez le guide du <3>sudoku pour seniors</3> pour les options de gros caractères et de confort. Consultez l’<4>index des techniques</4> complet, le guide <5>pour apprendre à jouer</5>, ou tous les niveaux sur la page <6>Niveaux de difficulté du sudoku</6>, ou retournez à l’<7>accueil</7>.\"],\"bUGU7d\":[\"La taille et la forme. Un wing est un motif fixe de trois ou quatre cases que l’on apprend à reconnaître d’un coup d’œil\u202F; une chaîne se construit lien après lien et peut atteindre n’importe quelle longueur, c’est pourquoi les chaînes se situent une bande entière au-dessus des wings sur l’échelle SE.\"],\"bVG9Tb\":[\"À imprimer\"],\"bY8tm0\":[\"Code source sur GitHub\"],\"bc8DGE\":[\"Remplissez chaque case vide avec un chiffre de 1 à 9 de sorte qu’aucun chiffre ne se répète dans une ligne, une colonne ou un bloc de 3×3.\"],\"c38U12\":[\"Qu’est-ce qu’une paire pointée\u202F?\"],\"c3R2ID\":[\"La dernière case libre et le singleton nu sont les deux premières stratégies que le moteur de résolution de Suuudokuuu essaie sur chaque grille, à chaque niveau de difficulté, parce que ce sont les déductions les moins coûteuses à vérifier. Ce qui distingue Novice, c’est que ce niveau est défini comme l’ensemble des grilles qui n’ont jamais besoin d’autre chose. En retirant davantage de chiffres, un solveur finit par bloquer sans singletons cachés, intersections ou sous-ensembles, et le générateur rejette ces grilles au lieu de les étiqueter Novice. Si vous savez lire une ligne et nommer le seul chiffre qui lui manque, vous avez déjà toutes les compétences qu’une grille Novice demande.\"],\"cJ_ZcY\":[\"Sudoku gratuit pour iOS, Android et le web, hors ligne dans les applications\"],\"cK6miM\":[\"Difficulté\"],\"cVxfVr\":[\"Non. Les deux techniques qu’exige une grille Novice se lisent directement sur la grille, et c’est exactement pourquoi ce sont les déductions les plus rapides du jeu.\"],\"d4hJrp\":[\"Niveau plus difficile\"],\"d5hiJp\":[\"Pourquoi les joueurs restent\"],\"dKAb7E\":[\"Chaque grille Enfer exige une chaîne forcée\xA0: aucune ne peut être résolue avec les techniques que Cauchemar autorise, jusqu’à l’AIC.\"],\"dXoieq\":[\"Résumé\"],\"do-_4n\":[\"Au moins un fish (<0>X-Wing</0> et ses variantes plus grandes et finned) ou un wing bivalué, en plus de toutes les intersections et de tous les sous-ensembles que les recueils plus faciles exigent déjà.\"],\"dvRtE-\":[\"Sept\xA0: Novice, Facile, Moyen, Difficile, Cauchemar, Enfer et Infini. Les grilles Enfer proviennent d’un corpus intégré et vérifié de grilles qui exigent chacune une chaîne forcée, au-delà de tout ce que demande Cauchemar, et <0>Infini</0> propose des grilles record comme Everest et AI Escargot.\"],\"dyGlGe\":[\"Le jeu en gros caractères reprend la même logique que le niveau Facile du recueil ci-dessus, mais avec \",[\"PRINTABLE_LARGE_PRINT_PUZZLES_PER_PAGE\"],\" grilles par page au lieu de \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\", de sorte que chaque case et chaque chiffre s’impriment nettement plus grand. Il convient aux personnes malvoyantes, aux fiches de classe lues à distance et à quiconque trouve la grille standard à l’étroit sur papier. Consultez la <0>page du sudoku en gros caractères</0> pour des conseils d’impression et l’alternative sur écran, ou le guide du <1>sudoku pour seniors</1> pour un tour d’horizon complet axé sur le confort.\"],\"e0NrBM\":[\"Projet\"],\"eBV_Xh\":[\"Les grilles Cauchemar comptent \",[\"clueCount\"],\" chiffres donnés et ont la garantie de demander au moins une technique de chaîne ou de coloriage, au-delà de tous les fish et wings.\"],\"eJ9n-i\":[\"Vous découvrez la grille elle-même\u202F? Commencez par le <0>guide pour apprendre à jouer</0>\xA0: les trois règles et vos premiers placements, avant de choisir un niveau ci-dessus.\"],\"eJum-4\":[[\"PRINTABLE_BOOKLET_SIZE\"],\" grilles réparties sur \",[\"PRINTABLE_BOOKLET_PAGE_COUNT\"],\" pages, imprimées \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" par page, avec les grilles résolues à la fin.\"],\"emFA81\":[\"FAQ du sudoku Cauchemar à imprimer\"],\"enA4B7\":[\"Le sudoku Difficile est-il plus dur que Cauchemar\u202F?\"],\"eo2JDj\":[\"Bloqué sur une grille\u202F?\"],\"eozBux\":[\"Pas forcément. Les grilles Enfer comptent de \",[\"HELL_CORPUS_MINIMUM_GIVEN_COUNT\"],\" à \",[\"HELL_CORPUS_MAXIMUM_GIVEN_COUNT\"],\" chiffres donnés, tirés d’un corpus intégré contrôlé par deux algorithmes de résolution indépendants et filtré pour ne garder que les grilles qui exigent une chaîne forcée, plutôt que générées au moment de l’impression.\"],\"ev-7sc\":[\"Non. Difficile plafonne au W-Wing\u202F; Cauchemar commence là où Difficile s’arrête et monte jusqu’aux chaînes d’inférences alternées. Les deux niveaux sont séparés par une frontière de techniques, pas par un nombre de chiffres donnés.\"],\"evANQd\":[\"Techniques de chaîne et de coloriage\xA0: X-Chain, XY-Chain, coloriage simple et AIC.\"],\"f0OFpM\":[\"<0>Enfer.</0> Bloque toujours sur les chaînes et l’AIC, et exige toujours une chaîne forcée, tirée d’un corpus intégré et vérifié.\"],\"fRl01D\":[\"Sudoku à imprimer\"],\"fUYszb\":[[\"PRINTABLE_BOOKLET_SIZE\"],\" grilles, imprimées \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" par page, avec un corrigé complet.\"],\"fY_UvT\":[\"C’est le recueil à imprimer pour une courte habitude quotidienne plutôt qu’une longue séance\xA0: glissez-le dans un carnet, résolvez une grille à la fois, et il n’y a jamais de candidat à noter ni de paire à suivre le long d’une ligne. Il convient aussi à une classe qui découvre les règles pour la première fois, puisqu’une classe entière peut terminer une grille dans le même court laps de temps sans que personne ne bute sur une intersection qu’on ne lui a pas encore apprise. La mise en page à \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" par page laisse chaque grille assez grande pour y écrire confortablement, même avec l’écriture d’un enfant, et le corrigé à la fin évite à l’enseignant de résoudre lui-même la feuille pour la vérifier.\"],\"fiJRay\":[\"Au moins une <0>paire pointée</0>, une <1>réduction bloc-ligne</1>, ou une paire nue ou cachée, en plus des singletons que les recueils plus faciles utilisent déjà. Aucune grille n’exige de fish, de wing ni de chaîne.\"],\"g4WRV6\":[[\"hellCorpusSize\"],\" grilles vérifiées de \",[\"HELL_CORPUS_MINIMUM_GIVEN_COUNT\"],\" à \",[\"HELL_CORPUS_MAXIMUM_GIVEN_COUNT\"],\" chiffres donnés, tirées du catalogue de grilles à 17 chiffres de tdoku et de la liste top1465 de magictour plutôt que générées à la demande.\"],\"g5Fk5U\":[\"Difficile\"],\"gJOrtn\":[\"Niveaux de difficulté\"],\"gh-p06\":[[\"clueCount\"],\" chiffres donnés sur 81 cases, avec la garantie de bloquer sur les singletons avant de céder à une intersection ou à un sous-ensemble.\"],\"gmWGv_\":[\"Une chaîne n’a pas de forme fixe, c’est pourquoi la marquer au crayon aide davantage ici qu’aux niveaux plus faciles.\"],\"gqWp2B\":[\"Une chaîne n’a pas de forme fixe\xA0: elle se construit lien après lien, et le seul moyen de s’y retrouver est de l’écrire. Sur papier, vous pouvez marquer chaque lien fort et faible au fur et à mesure, suivre l’alternance jusqu’à l’autre bout et voir aussitôt quelles cases les deux extrémités voient. C’est franchement pénible sur un écran de téléphone qu’il faut faire défiler. C’est aussi le recueil où une mauvaise élimination fait le plus de dégâts\xA0: si vous barrez un candidat qui aurait dû rester, tous les liens suivants sont faussés. Considérez donc les pages de solutions comme un vrai point de contrôle, pas comme une formalité.\"],\"h4IqRM\":[\"Vous repérez sans effort les intersections et les sous-ensembles\u202F? Passez au <0>Sudoku Difficile</0>, où un fish ou un wing est toujours requis, ou revenez au <1>Sudoku Facile</1> pour revoir les singletons. Vous préférez le papier\u202F? Téléchargez le <2>recueil de sudoku Moyen à imprimer</2>. Parcourez l’<3>index des techniques</3>, le <4>guide pour apprendre à jouer</4>, tous les niveaux sur la page <5>Niveaux de difficulté du sudoku</5>, ou retournez à l’<6>accueil</6>.\"],\"h6WxWJ\":[\"Idéal pour une résolution détendue\"],\"h7hJl_\":[\"Quelle est la difficulté de ces grilles\"],\"hw66JY\":[\"Grille 1 du recueil Facile, parmi les \",[\"PRINTABLE_BOOKLET_SIZE\"],\" du PDF.\"],\"i0qMbr\":[\"Accueil\"],\"i7-8lN\":[\"Des indices qui nomment la technique exacte à employer, pas seulement le prochain chiffre\"],\"iDOJbu\":[\"Un fish s’étend sur des lignes ou des colonnes entières, ce qui est plus facile à suivre en marquant les positions restantes d’un chiffre le long d’une colonne imprimée qu’en faisant défiler un écran. Les wings demandent la vue inverse\xA0: quelques cases bivaluées repérées d’un coup d’œil.\"],\"iEH6te\":[\"<0>Singleton caché</0>\xA0: un chiffre qui ne peut aller que dans une seule case d’une unité.\"],\"iggj45\":[\"Quelle est la difficulté du sudoku Facile\u202F?\"],\"ippIMU\":[\"Ces cases vides en plus par rapport à Novice suffisent pour que la grille cesse de se remplir toute seule avec les seules <0>dernières cases libres</0>. Une fois les placements évidents épuisés, une grille Facile laisse toujours au moins une case où le raisonnement par singleton caché est la seule voie\xA0: confrontez les chiffres manquants de chaque unité aux endroits où ils peuvent encore légalement aller, au lieu de lire les candidats directement sur une seule case. Le moteur de techniques de Suuudokuuu essaie le singleton caché en troisième, juste après la dernière case libre et le <1>singleton nu</1>, et une grille cotée Facile n’a jamais besoin d’aller plus loin\xA0: pas de paires pointées, pas de sous-ensembles, rien qui vous demande de garder plus d’une unité à l’esprit à la fois. L’écart entre les niveaux est petit à dessein\xA0: il tient exactement en une technique.\"],\"iu7tUI\":[\"Fil d’Ariane\"],\"iuw_bf\":[\"Cote de difficulté\"],\"iyTmPq\":[\"Chaque technique nommée est une façon plus rapide de suivre le même recoupement des lignes, des colonnes et des blocs sur de nombreuses cases à la fois.\"],\"j2fzAU\":[\"Les cotes SE sont les valeurs que publient des évaluateurs indépendants et la communauté des résolveurs de sudoku. Le cotateur de Suuudokuuu indique \",[\"SE_RATING_CEILING\"],\" avec un indicateur de plafond pour tout ce qui est plus difficile, et ne produit donc pas de chiffre propre pour ces grilles.\"],\"j2t1NI\":[\"Chaque niveau renvoie à une page complète avec un aperçu de grille jouable et les vrais faits sur la difficulté, tirés de notre <0>guide de la cote de difficulté du sudoku</0>. Le PDF, lui, n’a besoin que d’une imprimante.\"],\"jFRHhT\":[\"<0>Infini</0>\xA0: \",[\"infinityCorpusSize\"],\" des grilles les plus difficiles jamais publiées, choisies d’après leur cote SE publiée de \",[\"infinityLowestRating\"],\" à \",[\"infinityHighestRating\"],\" plutôt que d’après une plage de techniques, et hors de portée de toutes les techniques de l’échelle.\"],\"jJ8CSk\":[\"Notre échantillon de \",[\"sampleSize\"],\" grilles Difficile se mesure à SE \",[\"seRatingRange\"],\".\"],\"jMk3uh\":[\"Ne cherchez pas d’abord la case la plus difficile. Commencez par les placements les plus simples possibles, car les résoudre en premier rend aussi toutes les cases suivantes plus faciles.\"],\"jP5seF\":[\"Apprenez les techniques par ordre de difficulté plutôt que de mémoriser tous les motifs d’un coup. L’<0>index des techniques de sudoku</0> les recense de la dernière case libre jusqu’aux sous-ensembles, chacune avec un exemple détaillé.\"],\"jmetfY\":[\"Les grilles Facile demandent-elles parfois des notes au crayon\u202F?\"],\"juLzrc\":[\"Facile est le premier niveau où Suuudokuuu attend une vraie résolution, même douce. Une grille Facile compte \",[\"clueCount\"],\" chiffres donnés sur 81 cases, quelques-uns de moins que Novice. Les dernières cases libres et les singletons nus en remplissent encore l’essentiel, mais jamais la totalité\xA0: au moins une case demande toujours un <0>singleton caché</0>, c’est-à-dire un chiffre qui ne tient que dans une case d’une ligne, d’une colonne ou d’un bloc, même si cette case montre encore d’autres candidats. Ce motif supplémentaire est toute la différence entre Novice et Facile, et c’est une garantie, non une tendance\xA0: une grille qu’un solveur limité aux dernières cases libres et aux singletons nus peut terminer est rejetée parce qu’elle est trop facile pour ce niveau, et une grille qui exige plus qu’un singleton caché est rejetée parce qu’elle est trop difficile.\"],\"jwpEc6\":[\"Quand les placements faciles s’épuisent, suivre les candidats à la main devient essentiel. Un candidat, parfois appelé annotation au crayon, est un chiffre qu’une case peut encore légalement contenir d’après ce que sa ligne, sa colonne et son bloc contiennent déjà. Écrire chaque candidat dans une case, sur papier sous forme de petits chiffres dans le coin ou avec le mode notes d’une application, transforme une grille qui semble bloquée en une grille où des motifs deviennent visibles\xA0: les paires, triplets et quadruplets de candidats qui se répètent dans une unité sont exactement ce que les techniques comme les paires nues et les paires cachées sont conçues pour repérer. La méthode complète de chaque motif se trouve dans l’<0>index des techniques de sudoku</0>, et chaque terme utilisé dans ces guides est défini dans le <1>glossaire du sudoku</1>.\"],\"kFGAW9\":[\"Un petit nombre de chiffres donnés rend-il ces grilles difficiles\u202F?\"],\"kV-GNp\":[\"<0>Moyen</0>\xA0: \",[\"mediumClueCount\"],\" chiffres donnés, avec la garantie de bloquer sur les singletons avant de céder aux intersections et aux sous-ensembles.\"],\"kbLXsu\":[\"Corrigés inclus à la fin\"],\"kc2u3T\":[\"Éliminer les candidats case par case\"],\"lAIHWp\":[\"<0>Difficile</0>\xA0: \",[\"hardClueCount\"],\" chiffres donnés, avec la garantie de bloquer sur les sous-ensembles et de céder aux fish et aux wings.\"],\"lDdTS6\":[\"FAQ du sudoku Moyen à imprimer\"],\"lINilK\":[\"Le PDF s’ouvre sur une page de couverture indiquant le nombre de grilles et de pages, enchaîne avec \",[\"PRINTABLE_BOOKLET_SIZE\"],\" grilles imprimées \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" par page, et se termine par toutes les grilles résolues sur les dernières pages, de sorte que les réponses ne se trouvent jamais à côté d’une grille non résolue. Chaque grille est tracée avec des lignes vectorielles et la police PDF standard Helvetica\xA0: elle reste nette à toutes les tailles d’impression et ne dépend jamais d’une image numérisée. Notre échantillon publié de \",[\"sampleSize\"],\" grilles Novice se mesure à SE \",[\"seRatingRange\"],\", des chiffres que le <0>guide de la cote de difficulté du sudoku</0> mesure directement plutôt que de les supposer.\"],\"lPXkj-\":[\"Puis-je imprimer ce recueil Novice en gros caractères\u202F?\"],\"lQAsJI\":[\"<0>Règle de la colonne.</0> Chacune des neuf colonnes doit contenir une seule fois chaque chiffre de 1 à 9.\"],\"laMpeD\":[\"Cauchemar\"],\"lxRnL8\":[\"<0>Règle du bloc.</0> Chacun des neuf blocs de 3×3 doit contenir une seule fois chaque chiffre de 1 à 9.\"],\"lzXj7Z\":[\"Chaque grille de ce recueil exige une chaîne forcée\xA0: aucune ne peut être terminée avec les techniques que Cauchemar autorise, et chacune est tirée de notre corpus Enfer intégré et vérifié de façon indépendante plutôt que générée à la demande. Notre échantillon publié de \",[\"sampleSize\"],\" grilles situe ce niveau à SE \",[\"seRatingRange\"],\", avec le <0/> comme étape la plus difficile la plus fréquente. Voir le <1>guide des grilles à 17 chiffres</1> pour comprendre pourquoi ce n’est pas le nombre de chiffres donnés qui les rend difficiles.\"],\"mDD4iI\":[\"Oui, sans compte et sans filigrane, et la grille résolue de chaque puzzle est incluse à la fin.\"],\"mOCJOb\":[\"Quelques grilles Cauchemar à votre actif\u202F? <0>Sudoku Enfer</0> est le dernier niveau, où chaque grille exige une chaîne forcée. Revenez au <1>Sudoku Difficile</1> si les fish et les wings vous paraissent encore peu fiables. Vous préférez le papier\u202F? Téléchargez le <2>recueil de sudoku Cauchemar à imprimer</2>. Parcourez l’<3>index des techniques</3>, le <4>guide pour apprendre à jouer</4>, tous les niveaux sur la page <5>Niveaux de difficulté du sudoku</5>, ou retournez à l’<6>accueil</6>.\"],\"mVu64h\":[\"Les grilles Novice comptent \",[\"clueCount\"],\" chiffres donnés et ont la garantie de se terminer avec de simples dernières cases libres et des singletons nus.\"],\"m_1uBm\":[\"Sudoku du jour\"],\"mbw3Zs\":[\"Quels sont les niveaux de difficulté\u202F?\"],\"mdr9O2\":[[\"PRINTABLE_BLANK_GRID_PAGE_COUNT\"],\" pages\"],\"mf-vQH\":[[\"newbieClueCount\"],\" chiffres donnés, résolus avec de simples dernières cases libres et des singletons nus. Voir la <0>page Sudoku Novice</0> pour y jouer en ligne.\"],\"mqvuZQ\":[\"Apprendre à résoudre\"],\"n8c99d\":[\"Solveur de sudoku\"],\"o83Dls\":[\"Les grilles Facile comptent \",[\"clueCount\"],\" chiffres donnés et ont la garantie de demander au moins un singleton caché, et rien de plus difficile.\"],\"o8ErsC\":[\"Un sudoku peut-il avoir deux solutions\u202F?\"],\"oACpQU\":[\"Guides de difficulté\"],\"oF5_MF\":[\"Grande taille de texte\"],\"oFKMy-\":[\"Pas encore prêt pour les chaînes sur papier\u202F? Revenez au <0>recueil de sudoku Cauchemar à imprimer</0> pour le même raisonnement par chaînes avec une plus grande part de la grille remplie, ou au <1>sudoku Difficile à imprimer</1> pour les fish et les wings sans raisonnement en longueur de chaîne, ou jouez à Enfer sur écran sur la <2>page Sudoku Enfer</2>, où le même corpus alimente chaque grille. Prêt pour les grilles record\u202F? Le <3>recueil de sudoku Infini à imprimer</3> reproduit Everest, AI Escargot et d’autres grilles record.\"],\"oH36ji\":[\"Les grilles Infini ont-elles une solution unique\u202F?\"],\"oQ8R9m\":[\"Les grilles Cauchemar obligent-elles parfois à deviner\u202F?\"],\"oSfAuO\":[\"Sudoku Moyen\"],\"o_ys4H\":[\"Chaque grille Novice est cotée sur l’échelle SE (Sudoku Explainer) dès sa création. Notre échantillon publié de \",[\"sampleSize\"],\" grilles Novice se mesure à SE \",[\"seRatingRange\"],\", tout en bas d’une échelle qui monte jusqu’à 12, et sous ce que la plupart des tableaux fondés sur la cote SE prennent même la peine de nommer. Novice existe pour enseigner le recoupement ligne-colonne-bloc sur lequel reposent toutes les techniques suivantes, pas pour le tester. La plage mesurée pour ce niveau et pour tous les autres est publiée dans notre <0>guide de la cote de difficulté du sudoku</0>. Considérez une résolution Novice rapide et sans faute comme la confirmation que vous êtes prêt pour Facile, pas comme un record à battre pour lui-même.\"],\"oc75Be\":[\"Un sudoku bien formé n’en a jamais. Si une grille admet plus d’une complétion valide, elle est considérée comme défectueuse, car la logique seule ne peut plus conduire à une réponse unique.\"],\"ohi_6A\":[\"Pour chaque unité comportant plusieurs cases vides, vérifiez si un chiffre encore absent de l’unité ne peut aller que dans l’une d’elles, même si cette case a d’autres candidats.\"],\"p6O9l-\":[\"Combien de grilles contient le PDF de sudoku Infini à imprimer\u202F?\"],\"p95wx0\":[\"Les dernières cases libres et les singletons comme base, plus les paires pointées, les triplets pointés, la réduction bloc-ligne et les sous-ensembles nus ou cachés jusqu’aux quadruplets lorsque les singletons s’épuisent. Au moins l’une de ces techniques est toujours requise, et jamais rien de plus difficile.\"],\"pDFJMU\":[\"Téléchargez le PDF et ouvrez-le dans n’importe quel lecteur PDF, puis imprimez à 100\u202F% sur du papier US Letter. Chaque grille est tracée avec des lignes vectorielles et des polices PDF standard\xA0: il n’y a rien à pixelliser et aucune perte de qualité, quelle que soit la taille d’impression.\"],\"pIksP6\":[\"FAQ du sudoku Infini\"],\"pN5c2M\":[\"Sudoku Cauchemar\"],\"pOHwnD\":[\"Quelles techniques ce recueil Moyen exige-t-il\u202F?\"],\"pXows4\":[\"Suuudokuuu propose sept niveaux de difficulté\xA0: six qui exigent chacun un éventail de techniques plus large que le précédent, et Infini.\"],\"pe908p\":[\"Un chiffre donné, ou indice de départ, est un chiffre imprimé sur la grille avant de commencer. Un candidat est un chiffre que vous envisagez encore pour une case vide, d’après ce que sa ligne, sa colonne et son bloc excluent pour l’instant.\"],\"plp0e4\":[\"Jouer au sudoku Cauchemar maintenant\"],\"pu3rE1\":[\"Avec \",[\"clueCount\"],\" chiffres donnés sur 81 cases, ce recueil est le premier qui vaille la peine d’être résolu au crayon. Les singletons font avancer une grille Moyen jusqu’à un certain point, mais chaque grille bloque avec certitude sur eux, c’est le test que chacune devait échouer pour être imprimée ici, jusqu’à ce que vous repériez une <0>paire pointée</0> ou une <1>réduction bloc-ligne</1>, une intersection entre un bloc et une ligne qui ne fait qu’éliminer des candidats sans jamais placer un chiffre. Aucune grille du recueil n’exige de fish, de wing ni de chaîne.\"],\"q7QiGX\":[\"Comment jouer\"],\"qcBjCp\":[\"<0>Cauchemar</0>\xA0: \",[\"nightmareClueCount\"],\" chiffres donnés, avec la garantie de bloquer sur les wings avant de céder aux chaînes et au coloriage.\"],\"qiqtfW\":[\"Jouer au sudoku Moyen maintenant\"],\"qrmik6\":[[\"PRINTABLE_LARGE_PRINT_SIZE\"],\" grilles\"],\"qwJuVW\":[\"Pied de page\"],\"qyiPQ_\":[\"Facile est le recueil que l’on prend quand on veut terminer une grille sans trop réfléchir\xA0: dans le train, pendant une pause café, ou pour se détendre avant de dormir. Chaque déduction se lit encore directement sur la grille plutôt que sur une grille de candidats, il y a donc rarement une raison de noter un candidat dans la marge\u202F; le singleton caché demande de balayer une unité entière plutôt qu’une seule case, ce qui change les habitudes, pas la difficulté. C’est un format idéal pour en imprimer plusieurs d’un coup et venir à bout d’une petite pile en une semaine, puisqu’aucune grille n’exige la concentration d’une grille Moyen ou Difficile.\"],\"r2FUkM\":[\"Jouer à cette grille ici\"],\"r4WJmT\":[\"Techniques de sudoku\"],\"r7ajsb\":[\"Sans publicité, sans compte et sans suivi dans le jeu, sur le web comme dans l’application\"],\"r8BZnz\":[\"Faut-il un stylo et du papier pour résoudre un sudoku\u202F?\"],\"rFkWoz\":[\"Non. Chaque grille que génère Suuudokuuu est vérifiée comme ayant une solution unique au moment de la génération, si bien qu’aucune case n’oblige jamais à deviner, et les grilles Enfer intégrées sont en plus recoupées par deux algorithmes de résolution indépendants, un solveur à couverture exacte de type Dancing Links et un solveur à masques de bits, avant d’être livrées. Toute position qui semble ambiguë demande simplement une technique que vous n’avez pas encore essayée.\"],\"rISE1w\":[\"Quelles techniques faut-il connaître pour le sudoku Moyen\u202F?\"],\"rUmdf8\":[\"Le PDF de sudoku Difficile à imprimer est-il gratuit\u202F?\"],\"rUv2wg\":[\"C’est aussi le niveau source du PDF en gros caractères, avec un échantillon de \",[\"PRINTABLE_LARGE_PRINT_SIZE\"],\" grilles.\"],\"rcYOQY\":[\"Au moins une technique de chaîne ou de coloriage (les fish de niveau <0>swordfish</0> et les wings de niveau <1>XY-Wing</1> ne suffisent pas à eux seuls), en plus de tous les fish et wings que le niveau Difficile exige déjà.\"],\"rgh2Sh\":[\"Notre échantillon de \",[\"sampleSize\"],\" grilles Cauchemar se mesure à SE \",[\"seRatingRange\"],\".\"],\"rhRptr\":[\"C’est un vrai cap par rapport à Facile, mais chaque technique requise fonctionne encore à l’intérieur d’un seul bloc ou d’une seule ligne à la fois\xA0: les fish et les chaînes plus longs ne commencent qu’à partir de Difficile.\"],\"rjZpLn\":[\"Apprendre\"],\"rtx2YX\":[[\"easyClueCount\"],\" chiffres donnés, et chaque grille demande au moins un singleton caché, jamais davantage. Voir la <0>page Sudoku Facile</0> pour y jouer en ligne.\"],\"sMgCJW\":[\"Une grille qui demande un singleton caché ou une technique plus difficile est rejetée et régénérée, et n’est jamais étiquetée Novice.\"],\"sYhvIH\":[\"<0>Infini.</0> Les grilles de sudoku les plus difficiles jamais publiées, comme Everest et AI Escargot, choisies d’après leur cote publiée plutôt que d’après une plage de techniques\u202F; voir la <1>page Infini</1>.\"],\"sZN9TU\":[\"Fonctionne entièrement hors ligne une fois installé sur iOS ou Android\"],\"sf_Uq_\":[\"Notre échantillon de \",[\"sampleSize\"],\" grilles Novice se mesure à SE \",[\"seRatingRange\"],\".\"],\"sgcKNN\":[\"Toutes les règles du sudoku sont en réalité la même contrainte appliquée à trois types d’unités différents. Apprenez la contrainte une fois et vous connaissez déjà les trois règles.\"],\"sjwplg\":[\"Chaque recueil ci-dessous est un PDF de sudoku gratuit à imprimer, construit à partir des mêmes sources de grilles que celles jouées dans l’application\xA0: son générateur et ses détecteurs de techniques, et, pour Enfer et Infini, ses corpus intégrés et vérifiés. Choisissez une difficulté pour un recueil de \",[\"PRINTABLE_BOOKLET_SIZE\"],\" grilles avec les corrigés sur les dernières pages, ou prenez le jeu en gros caractères ou une grille de sudoku vierge plus bas. Sans inscription, sans publicité, sans filigrane.\"],\"ssPRl9\":[\"Le niveau le plus difficile de Suuudokuuu\xA0: \",[\"infinityCorpusSize\"],\" des grilles de sudoku les plus difficiles jamais publiées, chacune avec une cote SE publiée de \",[\"minimumRatingLabel\"],\" ou plus, à jouer gratuitement et sans publicité.\"],\"svA7xQ\":[\"Prêt pour une grille qui demande une idée de plus\u202F? Passez au <0>Sudoku Facile</0>, qui ajoute le singleton caché à tout ce qui précède. Vous préférez le papier\u202F? Téléchargez le <1>recueil de sudoku Novice à imprimer</1>, ou consultez le guide du <2>sudoku pour seniors</2> pour les options de gros caractères et de confort. Parcourez l’<3>index des techniques</3> complet ou le <4>guide pour apprendre à jouer</4>, ou retournez à l’<5>accueil</5> pour voir les sept niveaux sur la page <6>Niveaux de difficulté du sudoku</6>.\"],\"szlBSl\":[\"Liens de grilles à partager et rediffusion coup par coup de vos parties récentes, les 20 dernières par niveau\"],\"tHJbOh\":[\"Infini est-il plus difficile qu’Enfer\u202F?\"],\"tK6SRc\":[\"Chaque grille exige une chaîne forcée et est tirée d’un corpus intégré, vérifié de façon indépendante, de grilles de \",[\"HELL_CORPUS_MINIMUM_GIVEN_COUNT\"],\" à \",[\"HELL_CORPUS_MAXIMUM_GIVEN_COUNT\"],\" chiffres donnés.\"],\"tYB68O\":[\"Grille 1 du recueil Infini, parmi les \",[\"PRINTABLE_BOOKLET_SIZE\"],\" du PDF.\"],\"tc4WHX\":[\"Moins de chiffres donnés signifie-t-il toujours une grille plus difficile\u202F?\"],\"tc9127\":[\"Oui. \",[\"SITE_NAME\"],\" est gratuit et son code source est disponible, sans achats intégrés, sans abonnement et sans niveau de difficulté payant.\"],\"thMLRg\":[\"Difficile s’arrête au W-Wing\xA0: une grille qui résiste à tous les fish et à tous les wings est classée Cauchemar.\"],\"uFeI93\":[\"Chaque partie mélange la grille\xA0: une grille record familière n’a donc jamais deux fois le même aspect.\"],\"uy5vQS\":[\"Saisissez ou collez la grille dans le <0>solveur de sudoku pas à pas</0> et il nommera chaque coup (singleton caché, paire nue, X-Wing) au lieu de simplement remplir la grille. Il vérifie d’abord que votre grille a exactement une solution, et il s’exécute entièrement dans votre navigateur.\"],\"uyJsf6\":[\"À propos\"],\"v1_ToA\":[\"Les intersections et les paires se repèrent en marquant tous les candidats restants d’une unité\u202F; la mise en page laisse donc de la place dans chaque case précisément pour ces annotations au crayon.\"],\"vAJFgP\":[\"Idéal pour prendre l’habitude du sudoku\"],\"vEHxJQ\":[\"Niveaux de difficulté du sudoku\"],\"vLhN57\":[\"Notre échantillon de \",[\"sampleSize\"],\" grilles Difficile se mesure à SE (Sudoku Explainer) \",[\"seRatingRange\"],\", en plein dans la plage que la communauté des résolveurs associe aux fish et aux wings, et bien en dessous du territoire des chaînes au-delà de 7. L’étape la plus difficile la plus fréquente est le <0/>, et la plus difficile atteinte par l’échantillon est le <1/>. C’est ici que les joueurs occasionnels commencent à demander un indice\xA0: les fish et les wings sont faciles à décrire et vraiment difficiles à voir sur une grille en cours, attendez-vous donc à une résolution nettement plus longue et plus réfléchie qu’en Moyen. Consultez le <2>guide de la cote de difficulté du sudoku</2> pour toutes les données par niveau.\"],\"vNl4Yu\":[\"Facile commence à \",[\"clueCount\"],\" chiffres donnés, six de moins que Novice, et ajoute exactement une technique\xA0: chaque grille de ce recueil exige au moins un <0>singleton caché</0>, et aucune ne demande rien de plus difficile. Ce motif supplémentaire est ce qui en fait le recueil que l’on imprime pour une résolution détendue pendant une pause café plutôt que pour apprendre. C’est aussi le niveau source de notre PDF en gros caractères, avec un échantillon de \",[\"PRINTABLE_LARGE_PRINT_SIZE\"],\" grilles pour ceux qui veulent des cases plus grandes.\"],\"vXIe7J\":[\"Langue\"],\"vbOpg_\":[\"Pourquoi \",[\"SITE_NAME\"]],\"viJ4-_\":[\"Notre échantillon de \",[\"sampleSize\"],\" grilles Enfer se mesure à SE \",[\"hellSeRatingRange\"],\".\"],\"vlNS-q\":[\"Novice est le niveau débutant de Suuudokuuu, l’introduction la plus douce possible à la grille. Une grille Novice démarre avec \",[\"clueCount\"],\" des 81 cases déjà remplies. Chaque case restante se trouve avec les deux déductions les plus simples du jeu\xA0: une <0>dernière case libre</0>, quand une unité n’a plus qu’une seule case vide, et un <1>singleton nu</1>, quand la ligne, la colonne et le bloc d’une case écartent à eux trois huit des neuf chiffres. Ce n’est pas la description d’une grille Novice typique\xA0: c’est la règle que le générateur impose. Une grille candidate n’est acceptée comme Novice qu’une fois terminée par un solveur limité aux dernières cases libres et aux singletons nus. Aucune note au crayon, aucune logique d’élimination et aucune devinette ne sont jamais nécessaires.\"],\"voLlG5\":[\"Comment commencer à résoudre une grille de sudoku\"],\"vsge_o\":[\"Nouveau dans le sudoku\u202F?\"],\"vvCT_r\":[\"Où aller ensuite\"],\"vwz0Q4\":[\"PDF de \",[\"fileSizeKilobytes\"],\" Ko, format US Letter\"],\"wIwe3l\":[\"Comment l’échelle est construite\"],\"wRawiz\":[\"Suuudokuuu classe ses grilles sur une échelle de six niveaux, de Novice à Enfer, et chaque niveau se définit par deux faits concrets plutôt que par une étiquette marketing\xA0: le nombre de chiffres donnés au départ, et les techniques de résolution nommées que le niveau a la garantie d’exiger. Chaque nouvelle grille est aussi cotée sur l’échelle SE (Sudoku Explainer) dès sa création, par le même paquet de cotation que le <0>guide de la cote de difficulté du sudoku</0> utilise pour publier la plage de techniques et la plage SE mesurées de chaque niveau de l’échelle ci-dessous. Au-dessus de l’échelle se trouve <1>Infini</1>, un ensemble sélectionné de grilles record qui portent les cotes publiées par des évaluateurs indépendants, car elles dépassent le haut de notre propre échelle de cotation.\"],\"wT9V53\":[\"C’est avec Moyen que Suuudokuuu commence à demander des notes au crayon. Une grille Moyen compte \",[\"clueCount\"],\" chiffres donnés sur 81 cases, et les singletons seuls ne la terminent jamais\xA0: chaque grille du niveau a été confrontée à un solveur limité aux singletons et rejetée si celui-ci y parvenait. Une fois les dernières cases libres et les singletons épuisés, la grille reste bloquée jusqu’à ce que vous repériez une intersection (un chiffre confiné à l’endroit où un bloc et une ligne se recoupent) ou une paire verrouillée. Les <0>paires pointées</0>, les <1>triplets pointés</1> et la <2>réduction bloc-ligne</2> couvrent les intersections\u202F; les <3>paires nues</3> et les <4>paires cachées</4> couvrent le plus petit motif de sous-ensemble.\"],\"xI2Au1\":[\"Grille 1 du recueil Difficile, parmi les \",[\"PRINTABLE_BOOKLET_SIZE\"],\" du PDF.\"],\"xRTkBI\":[\"Infini\"],\"xTziZu\":[[\"PRINTABLE_BOOKLET_SIZE\"],\" grilles réparties sur \",[\"PRINTABLE_BOOKLET_PAGE_COUNT\"],\" pages, \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" par page, avec les grilles résolues à la fin.\"],\"xYaf-9\":[\"Enfer est-il plus difficile que Cauchemar\u202F?\"],\"xkW-Mi\":[\"Pourquoi ce recueil laisse-t-il plus de place autour de chaque chiffre\u202F?\"],\"xs4NvR\":[[\"SITE_NAME\"],\" est-il gratuit\u202F?\"],\"y-GOTe\":[\"Ensuite, regardez une case vide et barrez tous les chiffres qui figurent déjà dans sa ligne, sa colonne et son bloc. S’il ne reste qu’un seul chiffre, c’est un <0>singleton nu</0>, et vous pouvez le placer tout de suite. Si une case a encore plusieurs candidats, vérifiez si l’un d’eux ne peut aller nulle part ailleurs dans la même unité\xA0: c’est un <1>singleton caché</1>, tout aussi sûr à placer. À eux deux, ces motifs résolvent l’essentiel d’une grille facile sans raisonnement plus poussé.\"],\"yDLr5P\":[\"Sudoku en gros caractères\"],\"yNzy3T\":[\"Notre échantillon de \",[\"sampleSize\"],\" grilles Moyen se mesure à SE \",[\"seRatingRange\"],\", et \",[\"singlesOnlyPuzzleCount\"],\" grilles sur \",[\"sampleSize\"],\" se sont terminées avec les seuls singletons\xA0: c’est le premier niveau où ce nombre est nul par construction. L’étape la plus difficile la plus fréquente de l’échantillon est le <0/>, et la plus difficile atteinte est le <1/>. Les joueurs qui lisent couramment les annotations au crayon terminent une grille Moyen nettement plus vite que ceux qui suivent les candidats de tête, pour qui ce sera le premier niveau à vraiment récompenser l’écriture des candidats. Toutes les données par niveau figurent dans notre <2>guide de la cote de difficulté du sudoku</2>.\"],\"y_3zNL\":[\"Les dernières cases libres et les singletons nus en remplissent encore l’essentiel\u202F; le singleton caché est la seule addition par rapport à Novice.\"],\"yjTW_5\":[\"Quelles techniques faut-il connaître pour le niveau Enfer\u202F?\"],\"yy8xD2\":[\"La grille elle-même ne change jamais\xA0: neuf lignes, neuf colonnes et neuf blocs, soit quatre-vingt-une cases au total. D’une grille à l’autre, seuls changent les cases remplies au départ et les chiffres qu’elles contiennent, et c’est cette disposition de départ qui détermine la quantité de logique nécessaire pour atteindre l’unique solution valide.\"],\"z0P0h9\":[\"Notre échantillon de \",[\"sampleSize\"],\" grilles Enfer se mesure à SE (Sudoku Explainer) \",[\"hellSeRatingRange\"],\", avec le <0/> comme étape la plus difficile la plus fréquente et le <1/> comme étape la plus difficile atteinte par l’échantillon. Gardez-vous de voir dans le nombre de chiffres donnés la cause\xA0: le même échantillon situe <2>Cauchemar</2> à SE \",[\"nightmareSeRatingRange\"],\" avec \",[\"nightmareClueCount\"],\" chiffres donnés, et certaines grilles Enfer démarrent avec davantage de chiffres que cela. Ce niveau était autrefois construit uniquement à partir de grilles à 17 chiffres, et il n’était pas coté plus difficile que Cauchemar\u202F; sélectionner d’après la technique requise est ce qui sépare les deux. Notre guide <3>chiffres donnés et difficulté</3> démonte cet argument en détail, et le <4>guide de la cote</4> publie les tableaux par niveau.\"],\"zGCYA8\":[\"Puis-je jouer à AI Escargot et à Everest ici\u202F?\"],\"zX6n8C\":[\"Des grilles record comme Everest et AI Escargot, imprimées telles qu’elles ont été publiées. Voir la <0>page Sudoku Infini</0> pour y jouer en ligne.\"],\"zaRGXY\":[\"Grille de sudoku vierge\"],\"zdhNJO\":[\"FAQ du sudoku Moyen\"],\"zu-XZL\":[\"Sudoku Facile\"],\"zuuvDj\":[[\"PRINTABLE_BOOKLET_SIZE\"],\" grilles record, imprimées \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" par page, avec un corrigé complet.\"]}")as Messages;